module.exports=[30231,a=>{"use strict";a.s(["default",()=>b]);let b=(0,a.i(11857).registerClientReference)(function(){throw Error("Attempted to call the default export of [project]/src/components/LessonReader.tsx <module evaluation> from the server, but it's on the client. It's not possible to invoke a client function from the server, it can only be rendered as a Component or passed to props of a Client Component.")},"[project]/src/components/LessonReader.tsx <module evaluation>","default")},15803,a=>{"use strict";a.s(["default",()=>b]);let b=(0,a.i(11857).registerClientReference)(function(){throw Error("Attempted to call the default export of [project]/src/components/LessonReader.tsx from the server, but it's on the client. It's not possible to invoke a client function from the server, it can only be rendered as a Component or passed to props of a Client Component.")},"[project]/src/components/LessonReader.tsx","default")},2121,a=>{"use strict";a.i(30231);var b=a.i(15803);a.n(b)},31580,a=>{"use strict";var b=a.i(7997);a.i(70396);var c=a.i(73727),d=a.i(2121);function e(a){let{id:b,title:c,minutes:d=12,summary:e,sections:f,practice:g,quiz:h,laws:i,sources:j,labId:k,terms:l=[]}=a;return{id:b,title:c,minutes:d,summary:e,sections:f,practice:g,terms:l,lawIds:i,sources:j,labId:k,unit:Number(b.split(".")[0]),objectives:f.map(a=>`Explain ${a.title.charAt(0).toLowerCase()+a.title.slice(1)} and apply it to an investigation.`),question:{id:`q-${b}`,prompt:h[0],options:h[1],answer:h[2],explanation:h[3],unit:Number(b.split(".")[0])}}}let f=[e({id:"1.1",title:"Introduction to Law and Cyberspace",minutes:10,summary:"The internet changes the scale of human activity, not the need for lawful authority. Begin with the people, systems, and legal interests behind every digital interaction.",sections:[{title:"What cyberspace actually contains",body:["Cyberspace is the interconnected environment in which people create, exchange, and process digital information. It includes physical infrastructure such as cables, routers, data centres, and phones; logical layers such as addresses, protocols, accounts, and applications; and a human layer of identities, organizations, and decisions. A single message may pass through a handset, a local network, a service provider, and an overseas cloud service.","The internet is a network of networks, whereas the World Wide Web is one service carried over it. Email, messaging, online games, and payment APIs are not simply web pages. This distinction matters when identifying evidence: a browser history will not necessarily record a background application’s network connections. “Online” does not mean that the underlying device or server is physically located in the same country as its user."]},{title:"Why law applies across borders",body:["Cyber law is not one isolated code. Contract law can govern an online purchase, privacy principles can constrain the handling of personal data, criminal law can punish dishonest conduct, and procedural law governs investigation and trial. The Information Technology Act supplies technology-specific provisions, while constitutional protections and judicial decisions shape how those powers operate.","Jurisdiction concerns the authority to prescribe, adjudicate, and enforce rules. A victim in India, an accused elsewhere, and a platform holding records in a third country create different questions. Sections 1 and 75 of the IT Act address specified extraterritorial situations; they do not authorize Indian officers to search a foreign server unilaterally. Mutual legal assistance, letters rogatory, treaty mechanisms, and provider requests must be distinguished."]},{title:"A rights-based investigation",body:["An investigator protects both the integrity of evidence and the rights of the people connected to it. Authority, necessity, proportionality, purpose limitation, confidentiality, and accountability are practical safeguards. A complaint about one account does not automatically justify downloading every family photograph from a household device.","Start an investigation file with a precise question, its legal basis, the systems and date range in scope, and the least intrusive collection method. Record uncertainty instead of converting suspicion into fact. For urgent financial fraud, preserve transaction references and contact the bank and official reporting channels promptly; classroom technical experiments must never delay victim assistance."]}],practice:{title:"Map a single message",scenario:"Asha in Pune sends a payment instruction from her phone to a supplier whose mailbox is hosted abroad.",steps:["List the human, physical, and logical components in the message’s journey.","Identify three possible evidence sources: the handset, the mail service, and the recipient’s device.","Separate the question “Who controlled the account?” from “Where was the server?”.","Write one lawful local collection step and one question requiring provider or cross-border assistance."],debrief:"A useful map records custody and control as well as location. The existence of an overseas server does not prevent preservation of the original message on Asha’s lawfully accessed phone."},quiz:["Which statement best distinguishes the internet from the Web?",["They are different names for exactly the same service.","The Web is one application supported by the broader internet.","The internet contains no physical infrastructure.","Only the Web can carry digital evidence."],1,"The internet supports many services, including email and messaging; the Web is one of them."],laws:["it-act","bnss"],sources:["itact","constitution","cybercrime"]}),e({id:"1.2",title:"Concept and Evolution of Cyber Law",minutes:12,summary:"From legal recognition of electronic records to platform accountability and synthetic media: trace why the legal framework keeps changing.",sections:[{title:"From paper equivalence to digital regulation",body:["The UNCITRAL Model Law on Electronic Commerce, 1996 influenced the principle that information should not lose legal recognition merely because it is electronic. India’s Information Technology Act, 2000 introduced recognition for electronic records, authentication mechanisms, offences, and institutional powers. It also amended existing laws so that paper-based concepts could accommodate electronic processes, with specific exclusions that must be checked in the statute.","The 2008 amendment, brought into force in 2009, replaced the original section 66 and expanded the framework with provisions including sections 66A–66F, 67A–67C, and 69A. It introduced section 43A on reasonable security practices for specified body-corporate failures and section 79A for expert examiners. These provisions have different purposes and must not be treated as interchangeable."]},{title:"Institutions, privacy, and platform duties",body:["The 2011 SPDI Rules addressed specified sensitive personal data handled by body corporates. The 2015 Shreya Singhal judgment struck down section 66A and read down “actual knowledge” in the intermediary context. The 2017 Puttaswamy judgment recognized privacy as a fundamental right. The 2021 Intermediary Guidelines and Digital Media Ethics Code established due-diligence and grievance mechanisms, later amended for areas including online gaming and synthetic information.","The three new criminal laws commenced on 1 July 2024, replacing the IPC, CrPC, and Evidence Act subject to savings. The Digital Personal Data Protection Act, 2023 is a separate framework; enactment alone does not establish that every provision is operationally in force. A current answer should identify the version of the law, its commencement date, and its relationship to other regimes."]},{title:"Change is not automatic replacement of every rule",body:["A later notification may amend particular words in an earlier rule rather than replace the entire instrument. For example, the February 2026 amendment changed the 2021 Rules and added synthetic-media duties. The 2011 Rules are not simply “the 2021 Rules with a different year”. Likewise, repeal of the IPC does not erase earlier liabilities or pending proceedings.","For exam and practice answers, draw a timeline: enactment, notification, commencement, amendment, judicial interpretation. Use the official consolidated text where available, then inspect the amending notification and corrigenda. A news article or old textbook may accurately describe the past while being unreliable as a current statement of law."]}],practice:{title:"Build a legal timeline",scenario:"A textbook written in 2018 discusses section 66A and a section 65B certificate.",steps:["Place the IT Act, its 2008 amendment, Shreya Singhal, and the new criminal laws on a timeline.","Mark section 66A as struck down rather than merely amended.","Explain why a 2018 discussion of section 65B is historically useful.","Identify the current BSA provision and its Schedule without treating old judgments as irrelevant."],debrief:"Legal evolution is cumulative. Current procedure may change while older judgments still explain principles, subject to the new statutory text and later authority."},quiz:["When did the BNS, BNSS and BSA generally commence?",["26 January 2023","1 July 2024","1 January 2021","20 February 2026"],1,"The three new criminal laws generally commenced on 1 July 2024, with savings and transitional rules."],laws:["it-act","it-2021","bsa"],sources:["itact","shreya","privacy","bsa","it2026"]}),e({id:"1.3",title:"Cyber Jurisprudence: Meaning and Scope",minutes:11,summary:"Learn how courts interpret digital rights, state powers, and liability when existing legal principles meet unfamiliar technology.",sections:[{title:"Law in action, not just legislation",body:["Jurisprudence examines the concepts and reasoning underlying legal rules. Cyber jurisprudence asks what counts as a document, when access is authorized, how privacy survives sharing, and what makes a digital process fair. It draws on statutes, subordinate legislation, constitutional principles, precedent, and sometimes comparative law. A foreign judgment may illuminate a problem but does not automatically bind an Indian court.","Distinguish binding holdings from observations and dissenting opinions. Read the factual context and actual relief granted. Shreya Singhal concerned free expression and intermediary liability; Anvar and Arjun concerned proof of electronic records. Neither should be reduced to a slogan such as “all screenshots are inadmissible” or “every takedown is unlawful”."]},{title:"Rights, restrictions, and proportionality",body:["Articles 14, 19, 20, and 21 can be relevant to equality, expression, criminal safeguards, and life and liberty. Privacy is protected as a fundamental right, but restrictions require a lawful basis and must satisfy the applicable constitutional test. Puttaswamy discussed legality, legitimate aim, proportionality, and procedural safeguards. The exact test depends on the right and the challenged measure.","In evidence collection, identify the source of authority before assessing convenience. Employee monitoring, a complainant handing over their own phone, a search warrant, and compelled decryption are different situations. Selvi’s protections against involuntary narcoanalysis, brain-mapping, and polygraph tests should not be casually generalized into a universal rule governing every password request."]},{title:"Intermediary liability and actual knowledge",body:["Section 79 of the IT Act provides conditional safe harbour, not blanket immunity for platforms. Eligibility, intermediary functions, due diligence, and the circumstances in which liability arises all matter. Shreya Singhal interpreted actual knowledge in the context of court orders or appropriate government notification for the restriction involved; later rules and amendments must also be considered.","A reasoned answer separates the content creator’s liability, the platform’s duties, the user’s rights, and the state’s powers. It also distinguishes a blocking order, a grievance decision, and evidence preservation. Removing public access to a post does not necessarily require destruction of all underlying records, particularly where lawful preservation is needed."]}],practice:{title:"Write the issue before the answer",scenario:"A platform removes an investigative journalist’s post after a government communication.",steps:["Identify the claimant, decision-maker, and precise action challenged.","Frame separate issues for expression, statutory authority, and due process.","Read the relevant provision and the holding of the leading case.","List facts still needed, such as the order, notice, and appeal mechanism."],debrief:"Good jurisprudence begins with issue framing. A result cannot be justified merely by saying that the content is harmful or that the platform is private."},quiz:["What is the safest use of a foreign cyber-law judgment in an Indian exam?",["Treat it as binding Supreme Court precedent.","Ignore it because cybercrime is technical.","Use it as persuasive reasoning after checking Indian law.","Assume it replaces the IT Act."],2,"Comparative decisions can assist reasoning, but their domestic authority must be established."],laws:["it-act","bsa"],sources:["shreya","privacy","selvi","constitution"]}),e({id:"1.4",title:"Criminalization of Conduct in Cyberspace",minutes:12,summary:"A harmful online act is not automatically a particular offence. Match conduct, mental state, statutory ingredients, and lawful procedure.",sections:[{title:"Conduct, mental state, and prohibited result",body:["Criminal liability generally requires an act or illegal omission together with the mental element specified by the offence. Dishonesty, fraudulence, knowledge, intention, and consent have technical meanings. A failed login caused by a forgotten password is not equivalent to intentional unauthorized access. A misleading advertisement is not automatically the offence of cheating without the required dishonest inducement and other ingredients.","The IT Act contains computer-specific provisions such as section 43 damage, section 66 dishonest or fraudulent commission of specified acts, section 66C identity theft, and section 66D cheating by personation using a computer resource. General criminal provisions may also apply to conspiracy, forgery, extortion, or cheating. Avoid stacking charges solely because the word “cyber” appears in the complaint."]},{title:"Authorization and consent have boundaries",body:["Authorization can be limited by purpose, account, system, duration, and method. Permission to use a laptop for printing does not necessarily authorize copying a confidential database. “Without permission” in section 43 must be applied to the facts; a publicly reachable login page is not necessarily an invitation to access private records.","Consent to one use of personal information does not authorize every later use. Similarly, a person’s ability to open a publicly accessible URL does not make every scraping or investigative use lawful. Examine contractual restrictions, privacy rights, applicable law, and the investigative authority. Ethical review is especially important when research involves vulnerable people."]},{title:"From allegation to charge sheet",body:["Investigators should create an ingredient table: statutory element, supporting fact, evidence source, alternative explanation, and missing corroboration. For cheating by personation, identify the false identity, the communication, the dishonest intention, and the induced act. The account name alone rarely proves who typed a message.","Procedural safeguards remain relevant after identifying the offence. Check cognizability, territorial jurisdiction, limitation where applicable, and the version of the criminal law. BNSS section 534 contains savings, while BNS section 358 addresses continued operation of repealed enactments for specified prior matters. Do not mechanically use an old section number in a new case."]}],practice:{title:"The ingredient test",scenario:"An employee uses a valid work account to export customer data to a personal drive after being told not to.",steps:["Identify which systems and uses were authorized.","Separate policy breach from each possible statutory offence.","For each candidate offence, list the required mental element.","Preserve access logs, policy acknowledgments, and export records before drawing conclusions."],debrief:"A policy violation can support context without proving every crime. The prosecution still has to establish the statutory elements with reliable evidence."},quiz:["Which element is central to IT Act section 66D?",["Any use of a nickname online.","Cheating by personation through a computer resource.","Every breach of a website’s terms.","Owning more than one email account."],1,"Section 66D requires cheating by personation using a computer resource or communication device."],laws:["it-act","bns","bnss"],sources:["itact","bns","bnss"],labId:"email"}),e({id:"1.5",title:"Types of Internet Crimes and Cyber Offences",minutes:15,summary:"Recognize identity theft, intrusion, social-media abuse, deepfakes, digital arrest scams, terrorism, and espionage without confusing their legal definitions.",sections:[{title:"Computer as target and computer as instrument",body:["A computer-target offence attacks the confidentiality, integrity, or availability of a system: unauthorized access, damaging malware, or denial of service. A computer-enabled offence uses technology to facilitate fraud, stalking, extortion, impersonation, or unlawful trade. Many incidents combine both, such as mailbox compromise followed by invoice diversion. The classification should guide evidence collection rather than become a rigid label.","Identity theft under IT Act section 66C concerns fraudulent or dishonest use of specified identification features. Cheating by personation under section 66D focuses on inducing deception through an assumed identity. General cheating under BNS section 318 may also be relevant. A stolen password, a fake profile, and a transferred payment can be different stages of one incident, each requiring proof."]},{title:"Social harm and emerging deception",body:["Cyberstalking, voyeurism, obscene or sexually explicit electronic material, impersonation, and harassment involve different offences and victims’ rights. Preserve URLs, account identifiers, messages, context, and timestamps sensitively. Do not redistribute intimate material as part of an investigation. Deepfakes may facilitate fraud, defamation, impersonation, or sexual abuse; “deepfake” is not itself a complete statement of the charge.","A digital arrest scam involves a caller falsely claiming that police, a court, or another authority has confined or will arrest the victim unless money is paid. “Digital arrest” is not a recognized lawful arrest procedure or a standalone offence by that name. Investigate personation, cheating, extortion, or wrongful confinement as supported by facts. Genuine agencies do not demand transfers to a “safe account” to avoid arrest."]},{title:"Terrorism, espionage, and ordinary fraud",body:["Cyber terrorism is narrower than any serious computer incident. IT Act section 66F addresses specified acts intended to threaten India’s unity, integrity, security, or sovereignty, or strike terror, including conduct affecting critical information infrastructure under its conditions. BNS section 113 also has a distinct definition and safeguards. Ransomware is not automatically terrorism.","Cyber espionage describes covert acquisition of sensitive information, often for a state or organization. Attribution requires technical evidence plus context; an IP address or language setting is not conclusive. Classify the observed conduct, the victim’s harm, the suspected motive, and the legal basis separately. Use neutral terms until attribution is sufficiently supported."]}],practice:{title:"The video-call “police officer”",scenario:"A caller in uniform shows a forged warrant and tells a student to transfer money to avoid immediate arrest.",steps:["Stop payment and preserve the number, transaction reference, screenshots, and call details.","Identify the false identity, threatened harm, and induced transfer.","Discuss personation, cheating, and extortion without assuming terrorism.","Contact the bank and the official cybercrime channel; verify agency contact independently."],debrief:"The label “digital arrest” describes the scam narrative. The legal analysis still depends on conduct and statutory ingredients."},quiz:["What should you do if a caller demands a transfer to avoid “digital arrest”?",["Pay first and investigate later.","Keep the caller online while sharing an OTP.","Stop the interaction, preserve details, and contact the bank and official channels.","Forward the caller’s intimate recordings to friends."],2,"The demand is a scam indicator. Preserve evidence and use independently verified reporting channels promptly."],laws:["it-act","bns"],sources:["itact","bns","cybercrime","i4c","deepfake"],labId:"email"}),e({id:"1.6",title:"Overview of Information Technology Act and Cyber Laws",minutes:16,summary:"Navigate the IT Act by function: recognition, security, offences, interception, blocking, intermediary liability, and adjudication.",sections:[{title:"Recognition and security provisions",body:["Chapter II and related provisions recognize electronic governance, legal recognition of electronic records, and electronic signatures. Sections 4–10A address areas such as writing, signature, retention, and electronic contracts, subject to exclusions. Recognition does not dispense with proof of authenticity or compliance with other laws. Electronic signatures and Digital Signature Certificates are related but not identical to every form of scanned signature.","Section 43 addresses specified unauthorized acts causing damage and compensation; section 66 criminalizes dishonest or fraudulent commission of acts referred to in section 43. Sections 65 and 65B of the IT Act concern source-code matters and must not be confused with the old Evidence Act section 65B. Sections 66C and 66D address identity theft and cheating by personation."]},{title:"State powers and intermediary safeguards",body:["Section 69 concerns interception, monitoring, or decryption under prescribed conditions; section 69A concerns blocking public access in the interests specified by the statute; section 69B concerns specified traffic-data collection. These are different powers. BNSS section 94 provides the general power to require production of necessary documents or things, including electronic records. A production order is not automatically authority for a full device search.","Section 79 provides conditional intermediary safe harbour. Its operation must be read with section 79(2)–(3), the applicable Rules, and judicial decisions. Section 80 preserves specified police entry, search, and arrest powers for offences under the Act, subject to its conditions. The existence of a power does not remove constitutional, procedural, or documentation requirements."]},{title:"Institutions and routes to remedy",body:["CERT-In under section 70B is the national incident-response agency for specified functions. Section 70A previously designated NCIIPC functions concerning critical information infrastructure; institutional titles and notifications should be checked. The Controller and certifying authorities support electronic-signature infrastructure. Adjudication and appellate mechanisms have changed over time, so do not rely uncritically on old descriptions of a separate Cyber Appellate Tribunal.","A cyber incident may involve a police complaint, a civil claim, a regulatory report, a platform grievance, and preservation requests in parallel. Map the remedy to the objective: stop loss, preserve evidence, remove unlawful content, obtain compensation, or prosecute an offender. Keep originals and a record of what each recipient was asked to do."]}],practice:{title:"Choose the right power",scenario:"An investigator needs subscriber records from a service provider and also wants to block a public fraudulent page.",steps:["Separate the records request from the public-access restriction.","Locate BNSS section 94 and IT Act section 69A and read their conditions.","Identify who can authorize each action and what must be recorded.","Add evidence preservation so blocking does not become accidental destruction."],debrief:"A precise power-and-purpose map prevents the common error of treating all cyber investigative actions as one general permission."},quiz:["Which IT Act provision concerns blocking public access to information?",["Section 4","Section 43A","Section 69A","Section 66C"],2,"Section 69A addresses blocking for the specified statutory interests, following the applicable procedure."],laws:["it-act","it-2021","bnss"],sources:["itact","shreya","cert","rules"]}),e({id:"1.7",title:"Comparison of IPC/CrPC/Evidence Act with BNS/BNSS/BSA",minutes:18,summary:"Use a functional crosswalk—not a blind find-and-replace—to understand India’s criminal-law transition.",sections:[{title:"Three different jobs",body:["The IPC and now the BNS define general offences and punishments. The CrPC and now the BNSS provide criminal procedure. The Indian Evidence Act and now the BSA regulate proof in proceedings. The IT Act continues as a special law; it was not replaced by the BNS. A case can require all four: a BNS offence, BNSS procedure, BSA admissibility, and an IT Act provision.","The new laws generally commenced on 1 July 2024. BNSS section 534 and BNS section 358 contain savings and transitional provisions. The date of the conduct, investigation, proceeding, and the relevant legal action can matter. “Old case = always old procedure” and “new filing = always new substantive law” are both unsafe shortcuts."]},{title:"Important functional mappings",body:["Common offence mappings include IPC 419 to BNS 319(2), IPC 420 to BNS 318(4), IPC 465 to BNS 336(2), IPC 468 to BNS 336(3), and using a forged document under IPC 471 to BNS 340(2). These are study comparisons, not claims that every element and punishment is identical. BNS section 318 expressly retains the old section 420 reference in its marginal context, but always quote the operative provision.","For procedure, CrPC 91 corresponds broadly to BNSS 94, CrPC 154 to BNSS 173, CrPC 161 to BNSS 180, CrPC 164 to BNSS 183, and CrPC 165 to BNSS 185. Electronic FIR and audiovisual search provisions add procedural detail. Evidence Act 65A and 65B correspond broadly to BSA 62 and 63. BSA 63 adds an express certificate format and two signatories; the old form cannot simply be relabelled."]},{title:"A safe comparison method",body:["First identify the legal question. Next read the old provision, the new provision, and any amendment or saving clause. Compare elements, scope, exceptions, procedure, and punishment separately. Finally check case law interpreting the wording. Similar chapter placement does not establish equivalence. Some provisions are reorganized, expanded, omitted, or newly framed.","For a digital investigation, the most important practical change is not a new section number. It is the need to align collection, device particulars, hash documentation, and certification under the applicable evidence regime. The comparison tool in this course gives a quick orientation; the official bare Acts remain the authority for a filing or examination answer."]}],practice:{title:"Repair the old charge template",scenario:"A post-2024 complaint template alleges IPC 420 and attaches a certificate headed “Section 65B”.",steps:["Confirm the date and nature of the alleged conduct and applicable transition rules.","Compare the ingredients of IPC 420 with BNS 318(4).","Review the electronic output under BSA 63 and the current Schedule.","Record differences rather than merely replacing the headings."],debrief:"A defensible update checks substantive ingredients and evidentiary conditions. A certificate with the wrong statutory basis can create avoidable disputes."},quiz:["Which pairing correctly describes proof of electronic records?",["IEA 65B → BSA 63","IPC 420 → BNSS 94","CrPC 91 → BNS 318","IT Act 66D → BSA 63"],0,"BSA 63 broadly succeeds Evidence Act 65B, with important changes including the scheduled certificate."],laws:["bns","bnss","bsa","ipc","crpc","iea"],sources:["bns","bnss","bsa","ipc","crpc","iea"],labId:"certificate"}),e({id:"1.8",title:"National Cyber Regulatory Framework",minutes:12,summary:"See how government, regulators, incident responders, police, and sectoral authorities divide responsibility for cyberspace.",sections:[{title:"Institutions and their mandates",body:["MeitY administers the IT Act and significant parts of digital policy. CERT-In performs national cyber incident coordination and issues directions under its statutory mandate. The National Critical Information Infrastructure Protection Centre performs functions relating to protected systems and critical sectors. The Data Protection Board is associated with the separate DPDP framework, subject to commencement and establishment notifications.","At the operational level, local police, state cyber cells, and the Indian Cyber Crime Coordination Centre support cybercrime response. I4C is a coordination framework, not a replacement for every legally competent police station. Sector regulators, such as the Reserve Bank of India, may impose additional security and incident-reporting requirements on regulated entities."]},{title:"Different instruments, different force",body:["An Act creates primary legal obligations. Rules are delegated legislation made under an identified power. Directions and orders may implement specific statutory provisions. Policies, frameworks, advisories, and technical standards usually have different legal status. NIST CSF is a voluntary framework unless made applicable through a contract or another legal requirement; an ISO reference does not by itself create a criminal offence.","When responding to an incident, maintain an obligations register: instrument, issuing authority, applicable entity, trigger, deadline, recipient, and evidence of compliance. CERT-In’s 2022 directions include a six-hour reporting requirement for covered incidents, while other laws and regulators may impose additional duties. Do not assume that every organization or event has the same reporting clock."]},{title:"Coordination without losing accountability",body:["A good response plan assigns legal authority, technical containment, evidence preservation, communications, and victim support. These roles can overlap but should not be left ambiguous. Record who approved each intrusive action and who received each data copy. A service provider’s fraud team and a criminal investigator need different information and different assurances.","The National Cyber Security Policy, 2013 articulated objectives such as workforce development, information sharing, and a secure computing environment. It should be studied as policy, alongside but not confused with later binding rules. For current operational requirements, consult the responsible institution’s latest official notification rather than relying on a policy’s aspirations."]}],practice:{title:"The first coordination call",scenario:"A payment company detects account takeover affecting customers in several states.",steps:["List internal incident response, CERT-In, sector regulator, police, and customer-support roles.","Identify which reporting obligations are actually triggered.","Create one shared incident identifier without circulating unnecessary personal data.","Define the next update time and a decision log owner."],debrief:"Coordination succeeds when legal deadlines, technical decisions, and ownership are explicit. A long recipient list is not a response plan."},quiz:["Which statement about NIST CSF is most accurate?",["It is an Indian penal statute.","It automatically replaces CERT-In directions.","It is a framework whose legal effect depends on the context of adoption.","It certifies every tool as forensically sound."],2,"NIST CSF organizes cybersecurity risk management; it is not a criminal code or automatic product certification."],laws:["it-act","dpdp","policy-2013"],sources:["cert","i4c","policy2013","nist-csf","dpdp"]}),e({id:"1.9",title:"Information Technology Rules, 2011",minutes:13,summary:"Understand the SPDI Rules: notice, consent, purpose limitation, disclosure, security, and the limits of a compliance checklist.",sections:[{title:"Scope and sensitive personal data",body:["The Information Technology (Reasonable Security Practices and Procedures and Sensitive Personal Data or Information) Rules, 2011 were framed under section 43A read with section 87(2)(ob). They apply to body corporates handling covered data, with definitions and qualifications in the Rules. Rule 3 covers specified categories such as passwords, financial account information, health information, sexual orientation, biometric information, and certain records received for processing.","Information freely available in the public domain or furnished under the Right to Information Act is excluded from the SPDI definition. That exclusion does not mean all public information may be used for any purpose without legal or ethical consequences. The separate 2011 Intermediaries Due Diligence Rules should not be confused with the SPDI Rules merely because both share a year."]},{title:"Collection and disclosure duties",body:["Rule 5 addresses collection, notice, consent, lawful purpose, retention, review, withdrawal, and grievance contact. Sensitive-data collection requires consent in writing through letter, fax, or email under the Rule’s wording. The provider must use information for the purpose collected and retain it only as required or necessary under the stated framework. Consent is not the only legal concept relevant to an investigation.","Rule 6 regulates disclosure to third parties, subject to permission and specified exceptions including legally mandated government requests. Rule 7 addresses secure transfer. A compliance officer cannot simply approve a broad disclosure because a requester says they are investigating fraud; identity, authority, scope, and documentation still matter."]},{title:"Security practices and the current context",body:["Rule 8 addresses reasonable security practices, including documented policies, managerial and technical controls, and specified standards or audited practices. A named standard is not a guarantee against every breach. Investigators should examine actual access controls, risk assessment, monitoring, incident handling, and whether the implemented policy matched the system in question.","The DPDP Act, 2023 provides a separate personal-data regime, including a repeal pathway for section 43A when the relevant commencement notification is issued. Check current commencement and transitional material rather than assuming the 2011 Rules vanished when the Act was passed. For historical incidents, the version in force at the relevant time may be crucial."]}],practice:{title:"Audit a sign-up form",scenario:"A wellness app collects health details and a password but provides no purpose notice or grievance contact.",steps:["Classify the data under Rule 3 using the actual fields.","Compare the collection flow against Rule 5.","Identify the required consent, notice, and contact information.","Review security and retention rather than treating consent as the entire compliance exercise."],debrief:"A privacy review connects the user interface to data flows, contracts, security controls, and retention. A checkbox alone cannot cure unrelated deficiencies."},quiz:["What is the principal subject of the SPDI Rules, 2011?",["Digital signature certificate issuance only.","Reasonable security practices and sensitive personal data handling.","The replacement of the IPC.","International cyber warfare strategy."],1,"The SPDI Rules implement the section 43A framework for covered body corporates and sensitive personal data."],laws:["it-2011","dpdp","it-act"],sources:["rules","itact","dpdp","privacy"]}),e({id:"1.10",title:"Information Technology Rules, 2018",minutes:11,summary:"The syllabus label needs precision: the commonly intended 2018 instrument is an amendment to the Intermediary Guidelines Rules, 2011.",sections:[{title:"Identify the instrument correctly",body:["“Information Technology Rules, 2018” is not a sufficiently precise citation. In this syllabus it is commonly used for the Information Technology (Intermediaries Guidelines) Amendment Rules, 2018. These amended the 2011 Intermediaries Guidelines Rules. They are distinct from the SPDI Rules, 2011 and from the Interception, Monitoring and Decryption Rules, 2009.","The 2018 amendment process generated significant debate and a proposed replacement framework. A draft, a press release, a notified amendment, and a final rule in force are different documents. When citing a rule, record its full title, notification number, date, and operative text. This prevents a proposed obligation from being taught as binding law."]},{title:"Intermediary due diligence and unlawful content",body:["The 2011 framework required intermediaries to publish rules, privacy policies, and user agreements and to specify categories of prohibited content. The due-diligence conditions were linked to safe harbour under section 79. The Shreya Singhal decision had already affected the interpretation of actual knowledge and the use of the 2011 framework, so reading the bare notification without the judgment is incomplete.","Intermediary obligations depend on the service’s role. Hosting user content, transmitting data, and actively participating in unlawful conduct are not automatically equivalent. The later 2021 Rules replaced the 2011 Intermediaries Guidelines framework, but older events may still require historical analysis. The SPDI Rules are a separate instrument and were not simply replaced by that 2021 replacement clause."]},{title:"Practical records for a platform response",body:["A defensible platform process records the complaint, the exact URL or identifier, the asserted legal basis, the decision-maker, notice to the affected user where required, and the action taken. A request to preserve records should be distinguished from a request to remove content or disclose subscriber information. Each has different authority and retention implications.","For an exam, explain the naming ambiguity first, then discuss the relevant notified amendment and the later 2021 framework. Avoid inventing a standalone “IT Act, 2018”. The central learning outcome is accurate legal identification, not memorizing an incomplete shorthand from a course outline."]}],practice:{title:"Disambiguate a citation",scenario:"An old report says only “under the 2018 IT Rules, the platform had to act”.",steps:["Find the full title and notification date in the source material.","Determine whether the report refers to a draft or a notified amendment.","Check whether the incident predates the 2021 Rules.","Rewrite the citation and explain which version governs the asserted duty."],debrief:"A precise citation is itself an investigative safeguard. It lets another reviewer reproduce your legal reasoning."},quiz:["What should you do with the syllabus phrase “IT Rules, 2018”?",["Assume it is a new criminal code.","Identify the full instrument and distinguish amendments from drafts.","Treat every draft as binding law.","Assume it repealed the SPDI Rules."],1,"The commonly intended instrument is the 2018 amendment to the Intermediaries Guidelines Rules, 2011; exact identification matters."],laws:["it-2018","it-2011","it-2021"],sources:["rules","shreya","itact"]}),e({id:"1.11",title:"Social Media Ethics Code, 2021 and National IT Policy, 2013",minutes:16,summary:"Separate platform due diligence, digital-media ethics, and national cybersecurity policy—and understand the 2026 changes.",sections:[{title:"The three parts of the 2021 Rules",body:["The IT (Intermediary Guidelines and Digital Media Ethics Code) Rules, 2021 contain Part I introductory provisions, Part II intermediary due diligence, and Part III digital-media ethics. Part II includes Rule 3 duties and additional Rule 4 duties for significant social media intermediaries. Part III covers publishers of news and current affairs and publishers of online curated content, with different administrative mechanisms.","Grievance redressal, prescribed notices, and record-retention requirements must be read in the exact rule and version. Rule 3(1)(d) addresses removal following actual knowledge through the specified court or government route. Other complaint categories have their own conditions and clocks. The 2025 amendment tightened authorization and reasoning safeguards and changed the general specified removal window from 36 to 24 hours."]},{title:"Synthetic information: the 2026 amendment",body:["G.S.R. 120(E), notified on 10 February 2026, amended the 2021 Rules and generally commenced on 20 February 2026, with subsequent corrigenda. It introduced duties concerning synthetically generated audio, visual, or audio-visual information, including declarations, verification, labels, and provenance-related measures within the notified conditions. It also reduced the Rule 3(1)(d) window to three hours. Do not apply that clock to every grievance.","The definition and exclusions matter: not every edit or text-only model output is treated identically. The final text differs from the consultation draft, including proposed numerical label-size requirements. A platform response should inspect the notified Rule 3 and official corrections, not rely on a headline claiming that all AI content must carry a label of a fixed percentage of the screen."]},{title:"Policy is not the same as a rule",body:["The commonly intended 2013 policy is the National Cyber Security Policy, 2013, not a separate penal “National IT Policy”. Its objectives included a secure cyber ecosystem, workforce development, indigenous security technologies, information sharing, and incident response. It helped frame national priorities but does not itself supply every element of a criminal offence.","Compare policy and regulation through their legal effects. A policy may encourage capacity building; a Rule can impose a due-diligence condition; an Act can authorize a sanction. An organization can align with a policy while still failing a binding obligation. Keep the policy’s date and later strategies or notifications visible when discussing present-day governance."]}],practice:{title:"Triage three different complaints",scenario:"A platform receives a valid court removal direction, an impersonation complaint, and a report of a realistic AI-generated video.",steps:["Classify each request under the relevant part and rule.","Check the current removal clock and triggering conditions separately.","For synthetic media, review declaration, verification, and labelling duties and exclusions.","Document the decision, user notice, and preservation needs."],debrief:"The same platform can face different legal clocks and processes at the same time. One universal “24-hour takedown rule” is not an accurate answer."},quiz:["Which statement about the 2013 document is correct?",["It is the National Cyber Security Policy and is distinct from binding IT Rules.","It repealed the Evidence Act.","It created the BSA certificate Schedule.","It is identical to the 2021 Ethics Code."],0,"The 2013 policy sets cybersecurity objectives; the later Rules impose specific legal duties under the IT Act."],laws:["it-2021","policy-2013"],sources:["it2021","it2026","policy2013","rules"],labId:"email"}),e({id:"1.12",title:"International Cyber Regulations: NIST and ENISA Standards",minutes:13,summary:"Use international frameworks and threat reports intelligently, while keeping standards, laws, treaties, and evidence requirements distinct.",sections:[{title:"NIST: a risk-management framework",body:["NIST Cybersecurity Framework 2.0 organizes outcomes into Govern, Identify, Protect, Detect, Respond, and Recover. Govern emphasizes organizational context, responsibilities, policy, and supply-chain risk. The framework is outcome-oriented: it does not prescribe one product, guarantee security, or automatically certify a forensic examination. Profiles and implementation tiers help describe current and target risk management.","NIST SP 800-86 remains a foundational reference for integrating forensic techniques into incident response, while SP 800-61 Rev. 3 updates incident-response recommendations through the CSF lens. Use the latest applicable guidance and document the version used. A laboratory may adopt a NIST method, but Indian admissibility still depends on Indian law."]},{title:"ENISA and the European context",body:["ENISA is the European Union Agency for Cybersecurity. Its threat-landscape reports synthesize observed trends and support risk analysis; they are not a single binding “ENISA law”. EU instruments such as the NIS2 Directive and Cybersecurity Act have different functions. NIS2 concerns cybersecurity measures and supervision in covered sectors, while the Cybersecurity Act addresses ENISA and European certification frameworks.","When comparing jurisdictions, identify the entity, sector, location, and activity covered. A small Indian classroom lab is not automatically subject to an EU directive because it reads an ENISA report. International standards can inform reasonable controls and shared terminology, but legal applicability must be established independently."]},{title:"Cross-border cooperation and evidence",body:["The Budapest Convention addresses cybercrime and international cooperation. Signature, ratification, domestic implementation, and entry into force are different legal stages; India’s participation must not be assumed. The UN Convention against Cybercrime is another distinct process. Treaties do not normally replace the domestic procedure required for a search or disclosure.","For a cross-border request, preserve identifiers, timestamps with time zones, provider details, and the exact records sought. Use the competent authority and lawful channel. Publicly available information can often be collected locally, but covert access to a foreign account is not made lawful by calling it OSINT. Record source, acquisition method, and limitations for every international lead."]}],practice:{title:"Choose a framework, not a slogan",scenario:"A college wants a basic cyber-response plan and asks whether “NIST compliant” means legally immune.",steps:["Map one practical action to each CSF 2.0 function.","Identify applicable Indian reporting and evidence obligations separately.","Use an ENISA threat report to prioritize one plausible risk.","Write a limitation explaining what framework adoption does not prove."],debrief:"Frameworks improve decisions and communication. They do not replace statutory duties, competent investigation, or proof of what actually happened."},quiz:["Which list gives the six NIST CSF 2.0 functions?",["Search, seize, arrest, charge, try, punish","Govern, Identify, Protect, Detect, Respond, Recover","Collect, hash, convict, sentence, appeal, imprison","Plan, attack, exploit, persist, deny, evade"],1,"CSF 2.0 adds Govern to the five functions associated with the earlier framework."],laws:["nist","enisa","budapest"],sources:["nist-csf","nist-ir","enisa","budapest","un"]}),e({id:"2.1",title:"Introduction to Cyber Crime Investigation",minutes:10,summary:"A cyber investigation is a disciplined search for reliable answers, combining legal authority, technical examination, and human context.",sections:[{title:"Begin with a question, not a tool",body:["An investigation starts with an allegation or incident that can be stated precisely: who experienced what harm, when, through which account or system, and with what known loss. “Hack this person” is not an investigative objective. “Determine whether the supplier mailbox was compromised and whether the changed bank instruction caused the payment” identifies testable events and evidence sources.","The investigator distinguishes incident response from evidential investigation. Containment stops ongoing harm; forensics supports reliable conclusions. They overlap but can conflict, for example when rebuilding a server destroys volatile traces. A risk-based decision, made by an authorized person and documented, is better than an automatic shutdown or an unrecorded live examination."]},{title:"Roles and investigative authority",body:["The complainant supplies context and original records. The officer in charge directs the criminal investigation, a forensic examiner analyzes exhibits, service providers supply records within lawful authority, and prosecutors assess the proof required. A private security consultant does not automatically acquire police powers. An expert’s technical skill does not replace the legal basis for access.","In India, cyber cells, local police, and I4C-supported coordination may all be involved. The legally competent authority and jurisdiction must be identified. Specialized forensic support can be requested, but exhibit identifiers, scope, communication, and responsibility should remain clear. For urgent financial fraud, early reporting can help preserve the payment trail."]},{title:"A reproducible investigative plan",body:["Write the initial hypotheses and alternatives. A payment may follow account compromise, a deceptive but authentic message, malware, or an internal authorization failure. For each hypothesis, list expected observations and evidence that would disprove it. Avoid confirmation bias by actively looking for the innocent explanation.","Maintain an action log with time, actor, authority, action, result, and effect on evidence. Use synchronized time references and preserve originals. The plan should be revisited when new evidence appears. A defensible final report explains not only what was found, but also what was not available, what changed, and why a conclusion is limited."]}],practice:{title:"Frame the first five minutes",scenario:"A finance employee reports a suspicious invoice and a transfer made ten minutes ago.",steps:["Write a neutral one-sentence investigative question.","Identify urgent loss-prevention and preservation actions.","Assign the complainant, officer, examiner, and bank contact roles.","Record two hypotheses and the evidence needed to distinguish them."],debrief:"A focused opening prevents both delay and uncontrolled collection. Stopping further loss and preserving the original email can proceed in parallel."},quiz:["What is the best first step in a cyber investigation?",["Run every forensic tool available.","Define the allegation, scope, authority, and urgent preservation needs.","Assume the account owner is the offender.","Delete suspicious files immediately."],1,"A precise, authorized plan guides proportionate collection and protects the investigation from avoidable errors."],laws:["bnss","it-act"],sources:["bnss","cert","cybercrime"],labId:"acquisition"}),e({id:"2.2",title:"Stages of Cyber Crime Investigation Process",minutes:14,summary:"Move from complaint to report through iterative, documented stages without treating a process diagram as a substitute for judgment.",sections:[{title:"Intake, triage, and preservation",body:["Intake captures the complaint, identities, incident time, affected systems, financial loss, and available records. Triage prioritizes immediate danger, ongoing theft, evidence volatility, and legal deadlines. Verify contact details independently rather than calling a number supplied by a suspected scammer. Assign a case identifier and record the initial state without promising a result.","Preservation can begin with the complainant’s original messages, transaction records, and relevant device state. Request provider preservation through the proper channel when necessary. A preservation request does not itself disclose content. Record the exact scope and receipt time. Avoid editing original files or asking a victim to forward material repeatedly until provenance becomes unclear."]},{title:"Collection, examination, and analysis",body:["Collection acquires identified material using a suitable, authorized method. Examination extracts and organizes relevant artifacts from a verified working copy. Analysis interprets relationships, sequences, and competing explanations. These stages are related but distinct: finding a filename is an observation; concluding that a particular person intentionally created it requires additional evidence.","NIST SP 800-86 describes collection, examination, analysis, and reporting. Other models use identification, preservation, acquisition, analysis, and presentation. The terminology matters less than preserving integrity, documenting decisions, and making the process reproducible. Revisit collection when analysis reveals a new relevant source, but update the authority and scope where needed."]},{title:"Reporting, review, and feedback",body:["Reporting connects each conclusion to an exhibit, method, and limitation. A second examiner should be able to understand tool versions, settings, time normalization, and material transformations. Prosecutors and investigators may need clarification or further lawful collection. Evidence should remain available for independent examination under appropriate safeguards.","Close the case operationally without destroying evidence merely because a system is restored. Retention, return, and disposal require legal and organizational authority. Capture lessons: which logs were missing, which request was late, and which control would have reduced harm? An investigation should improve future prevention as well as address the present allegation."]}],practice:{title:"Sequence an invoice-fraud case",scenario:"You have a complaint, a mailbox export, a bank reference, and a suspect laptop, but no acquisition yet.",steps:["Record intake and preserve the available originals.","Define authority and prioritize volatile or short-lived records.","Acquire and verify the laptop through a suitable method.","Analyze the message and payment timeline, then draft a source-linked report."],debrief:"The stages can overlap. The important feature is that every transition has a documented purpose and does not silently alter the evidence."},quiz:["How does examination differ from analysis?",["Examination always proves intent; analysis does not.","They are identical operations.","Examination organizes artifacts; analysis evaluates their meaning and competing explanations.","Analysis occurs before any evidence is collected."],2,"Extracting an artifact and explaining its investigative significance are separate intellectual steps."],laws:["bnss","bsa"],sources:["nist-guide","cert","bnss"],labId:"acquisition"}),e({id:"2.3",title:"Legal Framework for Cyber Crime Investigation",minutes:15,summary:"Match each investigative action to a power, its conditions, and its safeguards under the applicable procedural law.",sections:[{title:"Complaint, production, and search",body:["BNSS section 173 governs information relating to cognizable offences, including specified electronic communication and signature requirements. Section 174 addresses investigation of cognizable cases. Section 94 provides for summoning production of documents or things, including electronic records, subject to its terms and exclusions. These are not interchangeable with a general search authorization.","Section 185 governs searches by police officers under its conditions, including recording grounds and the specified audiovisual documentation of search and seizure. Section 105 adds mandatory audio-video recording for specified searches, with implementation details to be checked. Section 106 concerns attachment of property derived from criminal activity in the situations it covers. Always read the current provision rather than relying only on old CrPC practice."]},{title:"Provider records and interception are different",body:["BNSS section 94 can support an order for necessary documents or things, including electronic records held by a person or intermediary, subject to its conditions and exclusions. Section 69 interception, monitoring, or decryption requires its own competent authorization and the 2009 Rules’ safeguards. Section 69A blocking is not a power to search every device. A request for historical records is not the same as real-time interception.","A subscriber record, traffic metadata, and message content can raise different privacy and statutory concerns. Minimize the request to relevant accounts and dates. Record the recipient, authority, delivery method, response, and verification. Where the provider is overseas, identify the appropriate legal assistance or other lawful route instead of assuming a domestic notice has unlimited reach."]},{title:"Rights, documentation, and exclusion of assumptions",body:["A device search must remain within lawful scope and be conducted with proportionate safeguards. Record the place, people, device state, identifiers, seized accessories, and reasons for each action. Where a person cannot supply a password, do not assume obstruction; self-incrimination, privilege, and the exact legal power require careful analysis. Selvi does not create a blanket answer for all biometric or password demands.","The applicable date determines whether a CrPC or BNSS provision governs, subject to savings. The IT Act and other special laws may add requirements. A legally sound file includes the order or authority, execution record, custody record, and examination report—not merely a forensic tool’s output. An educational checklist is not a warrant or legal advice."]}],practice:{title:"Build an authority register",scenario:"An officer seeks mailbox content, subscriber details, live interception, and a laptop search.",steps:["Create one row for each action, not one row called “cyber investigation”.","Locate the relevant BNSS and IT Act provisions.","Record the competent authority and required safeguards.","Flag live interception and overseas content for specialist legal review."],debrief:"Different data and different methods require different powers. Precision at this stage protects both the case and individual rights."},quiz:["Which BNSS provision broadly corresponds to CrPC section 91?",["Section 94","Section 173","Section 318","Section 63"],0,"BNSS section 94 broadly succeeds the production power in CrPC section 91; its actual text and limits still matter."],laws:["bnss","crpc","it-act"],sources:["bnss","crpc","itact","selvi","privacy"]}),e({id:"2.4",title:"Nature and Characteristics of Digital Evidence",minutes:11,summary:"Digital evidence is interpretable, replicable, fragile, and dependent on context. Its value comes from a defensible account of its source and meaning.",sections:[{title:"What makes digital evidence distinctive",body:["Digital evidence consists of information in electronic form that can support or refute a proposition. It may be a message, file, log, database row, location record, configuration, or metadata. A file is not a complete account of its creation. The surrounding system, user actions, clock settings, and later transfers all affect interpretation.","Digital data can be copied without removing the original, but a copy is not automatically equivalent in every technical respect. A screenshot can show visible content while omitting headers, file metadata, and surrounding messages. A forensic image can preserve unallocated sectors that ordinary file copying misses. Choose the representation that answers the question and document what it cannot show."]},{title:"Volatility, authenticity, and integrity",body:["Volatility describes how readily evidence changes or disappears. Memory, active connections, and running processes are generally more dynamic than an offline disk image, but cloud logs can also expire quickly. The familiar “order of volatility” is a planning heuristic, not an instruction to collect everything regardless of authority or risk.","Integrity means the data has not changed in an unauthorized or undocumented way. Authenticity concerns whether it is what it purports to be. Reliability concerns the process that generated it. A perfectly preserved forged email remains a forgery. Hashing supports integrity after acquisition; it does not establish that the original sender was honest or that the timestamp is correct."]},{title:"Context and uncertainty",body:["A filename, a user profile, and an IP address are contextual clues. Shared devices, remote control, clock drift, synchronization, and automated processes can disconnect an artifact from a human action. Record the source path, acquisition time, device clock offset, tool output, and relevant surrounding events.","Use explicit language: observed, inferred, and unverified. For example, “The export contains a message at 10:14 UTC” is an observation; “The employee sent it intentionally” is a conclusion requiring more proof. State alternative explanations and the evidence needed to test them. This discipline makes reports more persuasive, not less."]}],practice:{title:"Screenshot or export?",scenario:"A complainant supplies a cropped screenshot of a threatening chat.",steps:["Record what the screenshot visibly establishes and its source.","Preserve the original file without editing it.","Identify the account, full conversation, device, and export options.","List missing context and authentication information rather than declaring the sender proven."],debrief:"The screenshot can be useful evidence, but a fuller lawful export may improve context and verification. Neither format alone proves identity or truth."},quiz:["What does a matching hash primarily demonstrate?",["The content is truthful.","The compared data is identical to the hashed reference.","The sender’s identity is conclusively established.","The evidence is automatically admissible."],1,"A hash supports integrity comparison; authenticity, attribution, relevance, and admissibility require separate analysis."],laws:["bsa","iea"],sources:["bsa","cert","nist-guide"],labId:"hash"}),e({id:"2.5",title:"Sources of Electronic Evidence",minutes:12,summary:"Look beyond the visible document to devices, applications, networks, cloud services, and the people who control them.",sections:[{title:"Endpoint and removable-media artifacts",body:["Computers can contain documents, browser history, application databases, registry hives, event logs, shortcut files, shellbags, print artifacts, and memory dumps. External drives, memory cards, and phones may contain additional copies or synchronization records. The presence of an artifact can support a timeline, but its meaning depends on the operating system and application version.","Record device make, model, serial number, storage identifiers, state, connected peripherals, and relevant user accounts. A phone may depend on a paired cloud account; a laptop may contain only placeholders for cloud-hosted files. Do not assume that the device in front of you is the only or original source of every displayed record."]},{title:"Network and service-provider records",body:["Routers, firewalls, proxy servers, DNS logs, DHCP leases, authentication systems, and packet captures can connect a local device to network activity. DHCP is particularly useful when several devices share a public IP address. Provider records may include subscriber details, access logs, payment records, or content, each with different access conditions and retention periods.","Email headers can reveal a submission path, but received headers can be forged and internal paths may be obscured by relays. Payment records, merchant references, and account-control evidence can be more probative than an IP address alone. Ask for the provider’s interpretation of fields and time zones, and preserve the response in its original format."]},{title:"Cloud, wearable, and human sources",body:["Cloud audit logs, object versions, administrative actions, snapshots, and account tokens can reconstruct events outside a seized device. Smart watches, vehicles, cameras, and IoT applications may hold location or activity traces. Their data can be synchronized or transformed, so identify whether the export came from the device, a phone, or a remote service.","Witness statements, business-process records, and consent or authorization documents explain technical traces. A bank employee may confirm that a particular reference represents a settlement, not merely a payment request. Build a source matrix with custodian, location, acquisition method, expected retention, and legal limitations. This avoids overlooking short-lived evidence."]}],practice:{title:"Create a source matrix",scenario:"A disputed purchase was made through a shared home computer and a mobile payment app.",steps:["List endpoint, local network, provider, bank, and human sources.","Identify who controls each source.","Mark records likely to expire first.","Connect each source to a specific question, such as device-to-account association."],debrief:"A shared public IP is only one clue. Local leases, authentication events, and payment records may distinguish devices and account control."},quiz:["Why can DHCP logs be important in a shared-network investigation?",["They prove the identity of every user.","They may associate an internal address with a device at a particular time.","They decrypt all encrypted traffic.","They replace the need for lawful authority."],1,"DHCP records can help connect address assignments to devices, subject to clock accuracy and reliable interpretation."],laws:["bnss","bsa","it-act"],sources:["cert","nist-guide","bnss"],labId:"network"}),e({id:"2.6",title:"Collection and Preservation of Digital Evidence",minutes:16,summary:"Collect only what is authorized, preserve what matters, and make every material action explainable.",sections:[{title:"Prepare the scene and the method",body:["Confirm authority, scope, safety, and the evidence question before touching a device. Photograph connections and screen state where lawful and useful. Record the device clock against a trusted reference without changing it. Identify running encryption, remote wipe risks, volatile data, and business-critical services. Assign one person to maintain the scene and action log.","There is no universally correct “pull the plug” rule. Shutting down may lose memory and active connections; live acquisition may change the system and require trusted tools. A running enterprise server, an encrypted phone, and an offline laptop require different decisions. Document the selected method, expected changes, and the person who authorized the trade-off."]},{title:"Acquire and verify a working copy",body:["For suitable offline storage, a validated hardware write blocker helps prevent writes to the source. A bit-for-bit image can capture allocated and unallocated sectors, unlike a normal file copy. Record source and destination identifiers, tool and version, settings, start and end times, errors, and acquired size. Some formats store metadata and compressed segments; understand what the chosen format preserves.","Calculate a cryptographic hash of the acquired evidence and record it. Where the format permits, distinguish the hash of the source data from the hash of an image container. Verify the working copy before examination. A source hash may be impossible to reproduce exactly after a documented live acquisition; explain that limitation instead of inventing a match."]},{title:"Package, protect, and preserve access",body:["Use unique exhibit identifiers, tamper-evident packaging where appropriate, and controlled storage. Protect digital copies with access controls and encryption, and manage the keys separately. For phones, isolation from networks can reduce remote alteration but may affect battery and device state; follow a tested procedure and document the choice. Never place an unfamiliar device into an untested destructive mode.","Preservation letters to providers should identify the account, records, and relevant period without requesting unrelated data. Record acknowledgment and follow-up authority for disclosure. Keep originals sealed or access-controlled, examine working copies, and log any export. Preservation includes retaining context: headers, configuration, logs, and the documentation needed to interpret the content."]}],practice:{title:"The running encrypted laptop",scenario:"A lawfully seized laptop is logged in, disk encryption is active, and a remote-wipe capability may exist.",steps:["Record the visible state, clock, connections, and authorization.","Escalate to a qualified examiner and identify volatile-data risks.","Compare live collection and shutdown without applying a universal rule.","Document every change and prepare a custody record before transfer."],debrief:"A proportionate, expert-supported decision is safer than a memorized shutdown command. The record must let a reviewer understand why the method was chosen."},quiz:["What is the primary purpose of a hardware write blocker?",["To make a forensic tool run faster.","To prevent writes to the connected source device during suitable acquisition.","To prove the identity of the computer user.","To decrypt every disk automatically."],1,"A validated write blocker helps preserve the source; it does not prove attribution or automatically solve encryption."],laws:["bnss","bsa"],sources:["cert","nist-guide","bnss","bsa"],labId:"acquisition"}),e({id:"2.7",title:"Evidence Retrieval Techniques",minutes:12,summary:"Recover information through controlled exports, backups, filesystem analysis, and carving—while recording the limits of each method.",sections:[{title:"Logical, filesystem, and physical access",body:["A logical export uses an application or operating-system interface and may include only records visible to that interface. A filesystem acquisition extracts files and available metadata through the device’s storage abstraction. A physical acquisition seeks a lower-level representation where supported and lawful. These methods differ in completeness and in their ability to access deleted or protected areas.","Choose the least destructive method that can answer the question. A supported mail export preserving headers may be more useful than an indiscriminate disk image for one conversation. A mobile “full extraction” label is product-specific and does not guarantee every app, encrypted record, or deleted message. Record the device model, OS, tool, method, and known limitations."]},{title:"Deleted data and file carving",body:["Deleting a file often changes filesystem references before the underlying content is overwritten. Recovery may be possible from unallocated space, journal records, shadows, backups, or cloud versions. On SSDs, TRIM and garbage collection can make older recovery assumptions unreliable. Success depends on the device, filesystem, elapsed activity, encryption, and the specific deletion process.","File carving identifies files using headers, footers, or internal structures rather than filesystem entries. Fragmentation can defeat simple contiguous carving, and a recovered stream may lack its original filename, path, or timestamps. Do not silently assign recovered data to a user based only on its presence in unallocated space. Preserve the source location and recovery method."]},{title:"Recovery is a process, not a promise",body:["Use verified images or controlled exports, calculate hashes, and record tool settings. Work on copies so that recovery attempts do not alter the preserved source. Compare recovered records with independent sources such as mail attachments, backups, or provider logs. A match can strengthen context but does not erase uncertainty about who created the original.","Document unsuccessful attempts as well as successes. “No recoverable copy was found using this method” is different from “the file never existed”. Explain whether encryption, unsupported application formats, overwriting, or retention limits prevented retrieval. This distinction is essential in an honest expert report."]}],practice:{title:"Recover the missing attachment",scenario:"A user deleted an invoice attachment, but the message remains in a webmail account.",steps:["Preserve the message and its headers through a supported export.","Check attachments, trash, backups, and provider-supported versions lawfully.","If examining an image, record carving settings and source offsets.","Compare recovered content with the original message and state what cannot be recovered."],debrief:"A service export and a filesystem recovery answer different questions. Use the most reliable available source rather than assuming deleted means gone."},quiz:["What is a common limitation of header-and-footer file carving?",["It always restores the original filename and owner.","It cannot process digital data.","It may struggle with fragmented files and lose filesystem context.","It makes all recovered content authentic."],2,"Carving can recover content without the original directory entry, ownership information, or reliable timestamps."],laws:["bsa","bnss"],sources:["cert","nist-guide","bsa"],labId:"hash"}),e({id:"2.8",title:"Chain of Custody in Digital Investigations",minutes:13,summary:"The chain of custody is a continuous, testable account of who controlled an exhibit, what changed, and why.",sections:[{title:"Start the record at collection",body:["A custody record identifies the case, exhibit, description, source, collector, date and time, location, and relevant device identifiers. It should connect the physical item to its digital acquisitions and derived exports. A laptop, its disk image, and a recovered invoice may need distinct identifiers linked by a documented parent-child relationship.","Record each transfer with sender, recipient, purpose, time, condition, and acknowledgment. Include storage locations and access events under the organization’s procedures. For digital copies, access logs and integrity checks can supplement signed transfer records. A hash alone is not a chain of custody because it says nothing about who possessed the source."]},{title:"Explain transformations and exceptions",body:["Compression, format conversion, decryption, carving, and export can create new files. Preserve the original acquisition and document each transformation with its tool, settings, input, output, and hash. A report should distinguish the original exhibit from a working copy and a presentation excerpt. Redaction for disclosure should create a separate controlled copy, not overwrite the evidence.","If a seal is opened, record the reason, person, time, and replacement seal. If a hash differs, do not conceal it: identify whether the comparison concerns a container, extracted stream, changed live source, or corrupted copy. Investigate the discrepancy before relying on the affected material. Honest documentation of a problem is more defensible than a fabricated unbroken record."]},{title:"Custody supports, but does not decide, admissibility",body:["Courts evaluate the reliability of the evidence and the circumstances of its handling. A gap may invite challenge, but the legal consequence depends on the facts and applicable law. Avoid categorical claims that every minor documentation error automatically excludes evidence or that a hash cures every gap.","Prepare a custody appendix that a non-specialist can follow from seizure to courtroom. Link exhibit IDs used in the report, seizure record, laboratory receipt, and certificate. Store personal data securely and restrict unnecessary circulation. The goal is accountable continuity, not merely collecting signatures after the investigation has finished."]}],practice:{title:"Trace one invoice through the lab",scenario:"Exhibit L01 is a laptop; I01 is its image; D01 is a recovered invoice exported from I01.",steps:["Create a parent-child exhibit map.","Record the acquisition and transfer to the examiner.","Log the export and its hash separately from the image hash.","Explain which file is being certified and presented."],debrief:"Distinct identifiers prevent the common mistake of using a laptop’s serial number as if it identified every extracted file and later copy."},quiz:["Which information belongs in a transfer entry?",["Only the investigator’s initials.","Sender, recipient, time, purpose, exhibit identity, and acknowledgment.","Only the final court verdict.","A password for unrestricted public access."],1,"A transfer entry must make the movement and accountability of the exhibit reconstructable."],laws:["bsa","bnss"],sources:["cert","bsa","nist-guide"],labId:"acquisition"}),e({id:"2.9",title:"Admissibility of Electronic Evidence",minutes:15,summary:"An electronic file can be relevant and still require a proper route to proof. Separate admissibility, authenticity, and weight.",sections:[{title:"The route from record to document",body:["BSA section 57 includes electronic or digital records within documentary evidence. Section 61 addresses legal recognition of electronic records. Section 62 requires proof of electronic-record contents in accordance with section 63. Section 63 treats qualifying computer or communication-device output as a document when its conditions are satisfied. These provisions work together rather than as interchangeable slogans.","Distinguish the original electronic record from a printout, copied file, or other output. Section 63 addresses regular use, lawful control, ordinary input or derivation, and proper operation of the relevant device or combination of devices. A network, cloud service, or multiple-device process may require facts beyond the single handset in the witness box."]},{title:"Precedent and the current certificate",body:["Anvar held that the special electronic-record proof route in section 65B displaced the general secondary-evidence route for the output concerned. Arjun clarified the certificate position and disapproved the relaxation in Shafhi Mohammad. It also explained that production of the original device itself is a different situation from tendering a copy or output. These holdings must now be read with the BSA’s text.","For an output under BSA section 63, subsection (4) calls for a certificate at each instance of submission for admission, signed by the relevant person in charge and an expert, in the Schedule’s form. The Schedule includes Part A and Part B, source particulars, and hash information. Do not reuse an old one-signature section 65B template without checking the new requirements."]},{title:"Admissible does not mean conclusive",body:["Authentication, hearsay, relevance, privilege, and the manner of collection may raise separate issues. A certified chat can still contain a false statement or be misattributed. The court evaluates the evidence in context, including corroboration and the witness’s ability to explain the process. A certificate is not a declaration that every statement in the file is true.","Prepare the source witness, device custodian, and expert with accurate roles. Keep the original or reliable source available where lawful, preserve the full conversation, and disclose material limitations. The certificate builder in this course is a training worksheet, not a signed legal certificate or a guarantee of admissibility."]}],practice:{title:"The original-phone question",scenario:"A party proposes to bring the original phone to court rather than only submitting a chat printout.",steps:["Identify the precise record and the form in which it will be tendered.","Read BSA sections 61–63 and the Arjun clarification.","Separate original-device production from proof of copied output.","List the facts and signatures needed for the actual submission route."],debrief:"Do not answer “every phone needs a certificate” or “a screenshot never needs one” in the abstract. Identify the output, statutory route, and applicable precedent."},quiz:["Which distinction is most important when discussing electronic evidence?",["File size versus screen size.","Admissibility versus truth and evidential weight.","Laptop brand versus phone brand.","Internet speed versus download speed."],1,"A record may be admitted yet still be unreliable, false, or insufficient to prove the allegation."],laws:["bsa","iea"],sources:["bsa","bsa-schedule","anvar","arjun"],labId:"certificate"}),e({id:"2.10",title:"Section 63(4) BSA and Electronic Evidence Certification",minutes:18,summary:"Prepare a complete, truthful certificate worksheet that identifies the output, its source, the process, and the people able to explain it.",sections:[{title:"The statutory conditions",body:["Section 63(2) addresses regular use of the computer or communication device by a person with lawful control, regular feeding of the relevant kind of information, proper operation during the material period, and derivation of the output from that information. Where operation was interrupted or faulty, the question includes whether the fault affected the electronic record or its accuracy.","Section 63(3) addresses devices used singly, in a system or network, or in combination. Identify all materially relevant sources rather than describing only the final display device. For cloud-hosted records, the export workstation and the service generating the record may play different roles. The explanation must match the actual process, not a generic assertion that “the computer was working”."]},{title:"Part A and Part B",body:["Subsection (4) requires a certificate identifying the electronic record, describing how it was produced, giving appropriate device particulars, and addressing the conditions. It is to be signed by the person in charge of the device or relevant activities and an expert, in the Schedule’s form, at each instance of submission for admission.","Part A is completed by the party and identifies the source, make and model, serial or other identifiers, lawful control, ordinary operation, and hash particulars. Part B is completed by the expert and addresses the source and technical particulars, including the hash and algorithm. Attach the hash report. A person must not sign an expert portion merely because a form has a blank space; the roles and knowledge need to be genuine."]},{title:"Practical preparation and review",body:["Preserve the exact output being submitted and calculate its hash using a documented algorithm. SHA-256 is a sensible integrity choice for this course; the Schedule lists several algorithms and an appropriate other standard. Record file names, sizes, acquisition or export steps, device identifiers, time zone, tool versions, and relevant limitations. Keep the hash report consistent with the final paginated or exported output.","A certificate does not cure unlawful collection, false content, or an unexplained custody gap. Check who can competently sign each part and whether multiple devices or outputs require additional explanation. Obtain the current official Schedule and legal review before filing. The interactive worksheet deliberately remains marked as training material and cannot substitute for the required signatures."]}],practice:{title:"Prepare the invoice certificate worksheet",scenario:"A lawfully controlled laptop produced an exported invoice PDF and a SHA-256 report.",steps:["Identify the exact PDF, source device, and lawful controller.","Complete the party’s details and ordinary-operation explanation.","Add the expert’s actual particulars and attach the hash report.","Review both parts against the official Schedule and mark the classroom copy as training only."],debrief:"The certificate describes a real process. Accurate particulars and competent signatories matter more than polished wording copied from an unrelated case."},quiz:["Who signs the BSA Schedule certificate?",["Only the advocate, in every case.","The party and an expert in their respective parts.","Only the police officer who receives it.","No one; an unsigned hash is always sufficient."],1,"The Schedule provides Part A for the party and Part B for the expert, reflecting section 63(4)."],laws:["bsa","iea"],sources:["bsa","bsa-schedule","arjun"],labId:"certificate"}),e({id:"2.11",title:"Documentation and Reporting of Digital Evidence",minutes:12,summary:"Write a report that lets a reader trace every conclusion back to an exhibit and reproduce the important examination steps.",sections:[{title:"Structure for the reader",body:["Begin with the instruction, scope, examiner, dates, exhibit list, and question. Summarize findings without overstating them. Follow with the environment, methods, tools and versions, relevant settings, analysis, limitations, and conclusions. Put hashes, acquisition logs, custody records, and detailed timelines in appendices so that the main narrative remains readable.","Give every exhibit a stable identifier and connect it to its source. Describe what was examined, not only what was found. If a tool produced thousands of results, explain the selection criteria and whether material contrary to the hypothesis was considered. An expert report should help the court evaluate the evidence, not advertise the examiner or the software."]},{title:"Reproducibility and transformations",body:["Record time-zone normalization, clock offsets, decoding methods, search expressions, and relevant tool defaults. A timestamp shown in local time may differ from the underlying UTC record. A converted image or redacted excerpt is a new output; preserve its relationship to the original. Explain any error messages and whether they affect the relied-on result.","Separate observations from interpretations in the wording. “The log contains event ID 4624 at this time” is not equivalent to “the accused personally logged in”. Explain the event’s semantics, account type, and limitations. Where a second tool corroborates a result, describe what each actually verified rather than merely listing two product names."]},{title:"Review, disclosure, and presentation",body:["Use technical review to check calculations, exhibit references, and the logic of conclusions. A reviewer should identify unsupported leaps, inconsistent timestamps, and missing limitations. Maintain version control and preserve the underlying notes needed to explain the report. Follow applicable disclosure obligations rather than selectively presenting only supportive artifacts.","A clear visual timeline can help a non-technical reader, but every item should point back to a source. Avoid inflammatory labels and unnecessary personal data. If new evidence changes the conclusion, issue a transparent correction or supplement. Professional credibility depends on being willing to revise an opinion when the evidence changes."]}],practice:{title:"Repair an unsupported finding",scenario:"A draft says: “The suspect deleted the invoice at 22:10, proving fraud.” The only source is a file deletion timestamp.",steps:["Rewrite the observation without naming an actor.","Check the clock, filesystem semantics, and possible automated cleanup.","Identify evidence needed for attribution and intent.","Add a source-linked timeline and explicit limitations."],debrief:"A careful report can be both clear and cautious. It does not turn a filesystem event into proof of a person’s state of mind."},quiz:["Which statement is suitable for an expert report without further evidence?",["The suspect is definitely guilty.","The recovered file’s timestamp is 22:10 UTC; attribution requires further evidence.","Everyone using this software commits fraud.","The tool is popular, so its output needs no explanation."],1,"The report should distinguish the recorded artifact from conclusions about identity, intent, and criminal liability."],laws:["bsa","bnss"],sources:["bsa","cert","nist-guide"],labId:"certificate"}),e({id:"2.12",title:"Challenges in Handling Electronic Evidence",minutes:13,summary:"Plan for encryption, scale, cloud dependence, cross-border control, and fragile records without sacrificing rights or accuracy.",sections:[{title:"Technical barriers",body:["Encryption can protect legitimate privacy while limiting access to evidence. The correct response is not to assume guilt from refusal or to try arbitrary passwords. Identify the encryption layer, device state, available backups, key custodians, and lawful options. A cloud export or previously unlocked session may be more proportionate than invasive access, but only where authorized and reliable.","Volume and variety create triage problems. Multiple devices can contain duplicates, synchronized records, and inconsistent clocks. Anti-forensic techniques may alter logs or timestamps. Use known-good references, independent corroboration, and explicit uncertainty. SSD behavior, proprietary apps, and unsupported formats can make a familiar tool’s output incomplete."]},{title:"Organizational and cross-border barriers",body:["Cloud records may be controlled by a provider in another jurisdiction, stored across regions, and retained for a short period. A customer may possess only a limited audit-log export. Identify the tenant, account, service, region, custodian, and contractual access route. Send precise preservation and production requests through the competent channel, and record the provider’s response and limitations.","Human factors include incomplete complaints, pressure for quick attribution, lack of trained staff, and poor handoffs. Separate duties for collection, examination, and review where practical. Protect complainants and unrelated users by limiting access and redacting disclosure copies. Do not treat a victim’s private life as an unlimited investigative resource."]},{title:"Defensible decisions under uncertainty",body:["Use a decision register for material trade-offs: risk, options, authority, chosen action, expected impact, and outcome. If evidence cannot be preserved perfectly, explain what was possible and why. A live capture may be the only practical route; a missing provider log may be irrecoverable. Honest limitations are part of the evidential record.","Quality assurance should include validated tools, documented methods, peer review, secure storage, and retention schedules. A laboratory cannot promise that every challenge has a technical solution. Its professional obligation is to use a suitable process, avoid overstatement, and make the resulting evidence understandable and open to appropriate scrutiny."]}],practice:{title:"The expiring cloud log",scenario:"A relevant audit log will expire soon, but the provider is overseas and the tenant administrator is unavailable.",steps:["Identify the custodian and urgent preservation options.","Record the retention deadline and source time zone.","Choose the competent request route and minimize the requested scope.","Document unavailable data and avoid claiming a complete reconstruction."],debrief:"Early, precise preservation can matter more than a later perfect acquisition plan. Authority and honesty remain necessary when time is short."},quiz:["What is the most defensible response to an unavailable cloud record?",["Invent a plausible timestamp.","State the limitation, preserve related sources, and use lawful alternatives.","Assume the missing record proves the allegation.","Access an unrelated account without authority."],1,"Missing data must be disclosed. Related records and lawful preservation may help, but they do not justify unsupported conclusions."],laws:["bnss","bsa","dpdp"],sources:["privacy","nist-guide","budapest","bnss"]}),e({id:"3.1",title:"Introduction to Open Source Intelligence (OSINT)",minutes:11,summary:"OSINT turns lawfully accessible information into a documented, evaluated intelligence product—not an excuse for intrusive investigation.",sections:[{title:"Open source does not mean unrestricted use",body:["OSINT begins with information accessible without unauthorized access: public registries, official notices, public posts, published datasets, and openly reachable websites. Collection still raises privacy, terms-of-service, safety, and purpose questions. A leaked password database does not become ethical or lawful to exploit merely because someone posted it publicly.","Intelligence is the result of defining a requirement, collecting relevant information, evaluating sources, analyzing relationships, and communicating uncertainty. A pile of screenshots is raw material. The analyst must explain why a record matters, how it was obtained, and whether an alternative explanation remains plausible."]},{title:"Source, content, and identity are different",body:["Evaluate the source’s proximity to the event and the content’s internal consistency. A profile may accurately display a username while using a copied photograph. A domain-registration record may identify a privacy service rather than the operator. An archived page shows what a crawler captured, not necessarily what every visitor saw at that moment.","Keep source URLs, capture time, hashes where appropriate, and contextual screenshots. Separate the original record from annotations. Use independent corroboration rather than counting repeated copies of the same claim as separate sources. Public information can be outdated, manipulated, or intentionally planted."]},{title:"A requirement-led collection plan",body:["Write the question, authorized scope, permitted sources, stop conditions, and retention plan. For a suspected impersonation account, the question may be whether it reused a public alias and payment identifier—not where the person’s family lives. Exclude irrelevant personal details and protect the collected material.","Record confidence using consistent language. “Likely associated with the same operator” is different from “legally identified as the accused”. Consider shared devices, scheduled posts, compromised accounts, and copied branding. A good OSINT product makes its reasoning visible so a reviewer can challenge it."]}],practice:{title:"Scope a public-profile review",scenario:"A fictional shop reports an account copying its name and asking customers for advance payments.",steps:["Write one narrow identity-linkage question.","List public profile, official registry, and payment-reference sources.","Exclude private messages and family information from the initial plan.","Define two observations that would support a link and one that would weaken it."],debrief:"A precise requirement limits intrusion and improves the quality of the final assessment."},quiz:["What distinguishes intelligence from collected public posts?",["A larger number of screenshots.","Evaluation, analysis, context, and a defined requirement.","Use of an expensive tool.","Removing all source references."],1,"OSINT is an analytical process, not simply downloading anything visible online."],laws:["it-act","dpdp"],sources:["privacy","itact","nist-guide"],labId:"osint"}),e({id:"3.2",title:"OSINT Investigation Methodology",minutes:13,summary:"Use a repeatable cycle of direction, collection, processing, analysis, dissemination, and review.",sections:[{title:"Direction and controlled collection",body:["Translate the complaint into prioritized intelligence requirements. Identify known identifiers, time ranges, confidence levels, and gaps. Decide which public sources can answer each question and what authority would be needed for non-public records. Establish collection boundaries before curiosity expands the scope.","Capture the original page or record, URL, time, and relevant context. Use a controlled environment for untrusted content and avoid signing into a target account. Preserve a clean copy and record transformations. Where a platform limits automated collection, respect the applicable restrictions and choose a lawful alternative rather than bypassing controls."]},{title:"Processing and analytical discipline",body:["Normalize names, dates, and identifiers without silently changing the source. Build an entity table for accounts, domains, organizations, and payment references. Represent a relationship as an edge with a source and confidence, not an unexplained line on a chart. Keep contradictory records instead of deleting them to make the graph look convincing.","Use analysis of competing hypotheses. For a shared alias, consider the same operator, imitation, shared marketing staff, or an old transferred account. Seek discriminating evidence: a distinctive payment reference, independently verified registry contact, or a verified account migration notice. Repetition across scraper sites may still originate from one unsupported claim."]},{title:"Dissemination, review, and correction",body:["Produce a concise assessment with key judgments, supporting observations, source references, confidence, and alternatives. Mark inference explicitly. Share only with authorized recipients and remove unnecessary personal information from presentation copies. Preserve the underlying records under the retention policy.","Review the assessment when new evidence arrives or a source is corrected. Maintain an audit trail of changes and avoid silently rewriting history. An intelligence lead can justify further lawful collection, but it is not itself a conviction or a warrant. The handoff should state what investigators still need to establish."]}],practice:{title:"One alias, two explanations",scenario:"A public shop profile and a suspicious payment page share the alias “northstar-demo”.",steps:["Record both sources and the exact matching string.","Write same-operator and imitation hypotheses.","Seek an independent public identifier that discriminates between them.","Deliver a bounded judgment with confidence and next steps."],debrief:"Matching text is a lead. Independent, contextual corroboration is what changes its investigative value."},quiz:["Why use analysis of competing hypotheses?",["To make every clue look equally certain.","To reduce confirmation bias by testing plausible alternatives.","To avoid documenting sources.","To prove identity from a username alone."],1,"Competing hypotheses help identify evidence that distinguishes explanations rather than merely supports a favorite one."],laws:["it-act","bnss"],sources:["nist-guide","privacy","first"],labId:"osint"}),e({id:"3.3",title:"OSINT Tools and Techniques",minutes:14,summary:"Choose tools for a question, validate their output, and keep collection safe, reproducible, and proportionate.",sections:[{title:"Search, capture, and public records",body:["Search operators can narrow a public query by site, phrase, or filetype, but search-engine indexes are incomplete and time-dependent. Official registries and court or government publications provide identifiable provenance. Web archives can reveal earlier content, yet a missing archive is not proof that a page never existed. Record the query, date, and relevant result rather than only saving a cropped image.","A capture workflow should preserve the original response or export where feasible, record the capture environment, and hash significant files. Browser screenshots provide visual context but may omit dynamic content or headers. Tools change their interfaces and access rules; document the version and settings actually used."]},{title:"Infrastructure and media techniques",body:["WHOIS/RDAP, passive DNS, certificate transparency, and public reputation services can help connect domains and infrastructure. Each has limitations: privacy redaction, shared hosting, historical reuse, and delayed data. A certificate containing a domain name does not prove the owner’s identity or intent. Treat infrastructure relationships as leads with dates.","Reverse-image search can find earlier appearances of a photograph. Metadata, landmarks, and shadows may provide context, but stripped metadata is common and location clues can be staged. Do not geolocate a private residence unless it is relevant, authorized, and necessary. This course uses fictional records rather than asking learners to investigate real people."]},{title:"Tool safety and verification",body:["Browser automation, graph tools, and collection frameworks can accelerate repetitive work but can also leak credentials, execute untrusted content, or violate collection limits. Use an isolated environment, least-privilege accounts, and approved data handling. Never paste sensitive evidence into a random online “OSINT checker” without considering its retention and onward use.","Validate important findings through a second method or the original source. Record tool errors, rate limits, and unavailable fields. A result labelled “verified” by a platform may mean identity verification under that platform’s process, not proof of the investigator’s allegation. Tool names are less important than a defensible, repeatable method."]}],practice:{title:"Design a three-source check",scenario:"A public profile uses a company logo and links to a domain in the fictional dataset.",steps:["Capture the profile and the linked page with timestamps.","Compare the domain’s public registration information without assuming redacted fields.","Check whether an independent official source confirms the claimed organization.","Record one tool limitation and one privacy safeguard."],debrief:"Three copies of the same logo are weaker than one independent, relevant record. Tool output must be interpreted, not merely accumulated."},quiz:["What is a limitation of passive DNS?",["It reveals every keystroke on a server.","It proves who committed an offence.","It can show historical associations but may be incomplete or shared infrastructure.","It is the same as a lawful interception order."],2,"Passive DNS is contextual infrastructure intelligence, not a complete or conclusive attribution record."],laws:["it-act","dpdp"],sources:["privacy","nist-guide","mitre"],labId:"osint"}),e({id:"3.4",title:"Social Media Intelligence and Investigations",minutes:13,summary:"Preserve the account, content, context, and engagement without confusing online persona with verified identity.",sections:[{title:"What a social-media record should contain",body:["Record the platform, visible account name, stable identifier where available, post URL, capture time, time zone, and surrounding conversation. Display names and usernames can change. A screenshot of only one post may omit edits, replies, quoted content, or a link that explains the statement. Preserve a lawful export or original file when accessible.","Engagement counts are dynamic and can be manipulated. Save the observation time and avoid treating views as unique people or likes as agreement. Public follower lists reveal relationships but not necessarily personal acquaintance. A shared image may be a repost, parody, or evidence of impersonation."]},{title:"Account control and content interpretation",body:["A post originating from an account does not by itself establish which human used the keyboard. Shared credentials, delegated social-media tools, session theft, and scheduled publishing are alternative explanations. Authentication logs, device records, and witness context may be needed, and non-public records require lawful process.","For threats or harassment, preserve the exact wording, recipient, repetition, and relevant context. Do not amplify intimate or abusive material by circulating it in class. Use redacted presentation copies while retaining the original securely. A platform’s community-rule decision and a court’s legal finding are different determinations."]},{title:"Collection ethics and provider requests",body:["Use complainant-controlled access or genuinely public material within the authorized scope. Do not send deceptive friend requests or bypass access controls as a classroom exercise. Record why each collected item is relevant, especially where third-party comments contain personal information. Set a retention and access policy.","A preservation request can protect short-lived account records while legal process is arranged. A disclosure request should identify the account and relevant date range precisely. Follow the platform’s lawful-request process and applicable Indian authority. Downloading a profile does not preserve the provider’s underlying logs or deleted backend records."]}],practice:{title:"Preserve a changing profile",scenario:"A fictional account repeatedly changes its display name while posting the same payment request.",steps:["Capture the stable identifier and each observed display name.","Save full context and timestamps, not just cropped text.","Separate account-control evidence from content evidence.","Draft a narrow preservation request for relevant provider records."],debrief:"Stable identifiers, context, and time-aware capture make later analysis more reliable than a folder of unlabelled screenshots."},quiz:["Why preserve a stable account identifier where available?",["It conclusively identifies the human operator.","Display names can change, while an identifier may help link records.","It removes the need for context.","It proves every post is true."],1,"An identifier helps connect changing profile records, but account control and human attribution still require evidence."],laws:["it-2021","bnss","bsa"],sources:["it2026","cert","privacy","bsa"],labId:"osint"}),e({id:"3.5",title:"Deep Web: Concepts and Investigation Methods",minutes:10,summary:"The deep web is content not indexed by ordinary search engines; it is not a synonym for criminal activity or the dark web.",sections:[{title:"Understanding non-indexed content",body:["Search engines discover and index a subset of accessible web content. Pages behind logins, dynamic database responses, private dashboards, paywalls, and pages excluded from crawlers may be part of the deep web. Ordinary email inboxes, bank portals, and internal business systems illustrate why non-indexed does not mean illicit.","A page’s absence from a search result can have many causes: authentication, robots exclusion, crawling limitations, recent publication, or technical errors. It does not establish deliberate concealment. “Deep web investigation” therefore begins with identifying the access mechanism and the lawful authority to use it."]},{title:"Authorized access and reliable exports",body:["For a complainant’s own account, use supported export tools and preserve the original response, headers, and relevant metadata. For organizational systems, define the account, role, tenant, and date range. A screenshot of a dashboard may not show filters or time-zone settings that materially change interpretation.","Do not bypass authentication, exploit a vulnerability, or reuse leaked credentials as an OSINT shortcut. If records are relevant but inaccessible, seek consent, provider assistance, or competent legal process. Record what the export includes and excludes, especially for paginated or dynamically loaded content."]},{title:"From private records to investigative leads",body:["Authenticated records can be highly probative because they connect activity to account sessions, roles, and business processes. Yet logs can reflect automated actions or administrator impersonation. Corroborate important events with audit trails, payment records, and independent context. Preserve the query and export settings.","Where a lawful investigation leads from a public page to a login-protected resource, stop at the boundary and reassess authority. The technical ability to guess an identifier is not permission to retrieve another person’s information. Explain this boundary in the report so the reader understands why collection stopped."]}],practice:{title:"Export an authorized dashboard",scenario:"A shop owner consents to export their own store’s order history for a disputed transaction.",steps:["Confirm the owner’s control and define the transaction date range.","Record filters, time zone, and export format.","Preserve the original export and calculate its hash.","Identify backend records that only the provider can supply."],debrief:"Deep-web material can often be collected through ordinary lawful account access. The export’s scope and provenance matter more than the label."},quiz:["Which is a typical deep-web example?",["A public news homepage indexed by search engines.","An authenticated bank account dashboard.","Every page on the Tor network.","A printed newspaper."],1,"The deep web includes non-indexed content such as authenticated dashboards; it is broader than anonymity networks."],laws:["it-act","bnss"],sources:["itact","nist-guide","privacy"]}),e({id:"3.6",title:"Dark Web: Structure and Investigation Techniques",minutes:13,summary:"Understand overlay networks and investigative boundaries without treating anonymity itself as evidence of an offence.",sections:[{title:"Structure and legitimate uses",body:["The dark web refers to services on overlay networks that require particular software or configuration, commonly including Tor onion services. These systems can support privacy, journalism, and access under restrictive conditions as well as illicit markets. Use of anonymity technology is not, by itself, proof of criminal conduct.","Onion services use a different addressing and routing model from ordinary public websites. Hidden-service directories, introduction points, and rendezvous circuits help conceal aspects of the connection. Investigators should understand the architecture at a conceptual level; operational deanonymization is a specialized, legally constrained activity, not a classroom scanning exercise."]},{title:"Passive collection and provenance",body:["A safe learning workflow uses supplied fictional pages or authorized passive observations. Preserve the visible content, capture time, relevant identifiers, and acquisition limitations. Do not purchase illicit goods, download unknown executables, or interact with abuse material. If such material is encountered unexpectedly, stop and follow the organization’s legal and safety procedure.","Marketplace claims, vendor names, and escrow addresses can be false or reused. Cryptocurrency transactions may provide a public ledger trail, but address ownership and transaction purpose require additional evidence. A payment graph does not automatically identify a person. Preserve the complete source and distinguish observed ledger data from inferred clustering."]},{title:"Operational and legal limits",body:["Covert account interaction, exploitation, and network investigative techniques can affect privacy, jurisdiction, and evidential reliability. They require specific authority, careful planning, and trained personnel. A general authorization to browse public information should not be stretched into permission to deploy malware or take over a service.","Record the technical environment and any changes it makes. Routing, clock differences, and service instability can complicate timestamps. Cross-border cooperation may be needed for infrastructure records. The report should explain how the material was obtained and why the conclusion does not depend on unsupported assumptions about anonymity or location."]}],practice:{title:"Evaluate a supplied marketplace claim",scenario:"A fictional archived page claims that a vendor operates from a particular country.",steps:["Record the claim as page content, not verified location.","List alternative explanations such as copying, deception, or shared branding.","Identify lawful corroborating sources without contacting the vendor.","Write a confidence statement and operational safety limits."],debrief:"The safest useful analysis often begins with source evaluation. Technical reach is not the same as legal permission or reliable attribution."},quiz:["What follows from a person’s use of an anonymity network?",["They have necessarily committed a crime.","Their identity is conclusively known.","Nothing conclusive about criminality follows without additional evidence.","All their communications are public."],2,"Anonymity technology has lawful and unlawful uses. Conduct and statutory elements must be established separately."],laws:["it-act","bnss","budapest"],sources:["budapest","nist-guide","privacy"]}),e({id:"3.7",title:"Introduction to Digital Forensics",minutes:12,summary:"Digital forensics applies systematic, reproducible examination to digital material while preserving integrity and explaining uncertainty.",sections:[{title:"Forensic science, not tool operation",body:["Digital forensics concerns the identification, preservation, examination, analysis, and presentation of digital information for a legal or investigative purpose. Running a recovery program is only one possible operation. The forensic quality comes from authority, method, documentation, validation, and an explanation that can be tested by another examiner.","Locard’s exchange principle is often used as an analogy for digital traces, but not every action leaves a recoverable artifact and not every artifact has the meaning it first appears to have. Logging may be disabled, clocks may differ, and data may be synchronized. Use scientific reasoning rather than treating a tool’s output as unquestionable truth."]},{title:"Principles and repeatability",body:["Preserve the original where practicable, examine verified working copies, and document necessary changes. Use methods appropriate to the question and explain their limitations. Maintain continuity from source to result. A second examiner should be able to understand the important steps and reach a comparable observation, even if proprietary software prevents exact interface replication.","Validation asks whether a tool or method performs as claimed for the relevant task. Verification asks whether a particular acquisition or copy matches the reference. These concepts are complementary. A validated tool can be misconfigured, and a matching hash does not validate every analytical interpretation produced by the tool."]},{title:"Form and test hypotheses",body:["Translate the investigative question into expected artifacts. If an attachment was opened, consider application records, recent-file references, browser downloads, and temporary files. If a device was connected, consider system logs and device identifiers. Seek both supporting and contrary evidence and record why artifacts may be absent.","Distinguish event time, recorded time, and acquisition time. State confidence and alternatives. A forensic conclusion can be useful without being absolute: “These artifacts are consistent with the file being opened under this account” may be the strongest supportable statement. Overstatement can damage both the case and the examiner’s credibility."]}],practice:{title:"From question to artifact",scenario:"You must assess whether a spreadsheet was opened before a disputed email was sent.",steps:["Write the event and time window precisely.","List expected artifacts and their limitations.","Define a contrary observation that would weaken the hypothesis.","Plan analysis on a verified copy and preserve source references."],debrief:"A forensic method is driven by a question and testable expectations, not by opening every artifact a tool happens to display."},quiz:["What makes an examination forensic?",["A commercial software logo.","A lawful, documented, reliable, and reviewable process.","The examiner’s confidence alone.","The number of recovered files."],1,"Forensic quality comes from method, integrity, documentation, and accountable interpretation—not a product label."],laws:["bsa","bnss"],sources:["cert","nist-guide","bsa"],labId:"hash"}),e({id:"3.8",title:"Device and Computer Forensics",minutes:15,summary:"Examine storage, operating-system artifacts, applications, and memory as parts of one system rather than isolated files.",sections:[{title:"Storage and filesystem context",body:["A disk image can preserve partitions, filesystem metadata, allocated files, and unallocated space. NTFS, APFS, ext4, and other filesystems record different artifacts and timestamp semantics. A modified time may change because of synchronization, metadata updates, or software behavior. Record the filesystem and tool interpretation before building a timeline.","On Windows, registry hives, event logs, prefetch, shortcuts, jump lists, and shellbags can help reconstruct program execution, file access, and device connections. Their presence and detail depend on configuration and version. On Linux and macOS, examine the corresponding system logs, application databases, and configuration records rather than applying Windows assumptions."]},{title:"Memory and running state",body:["RAM may contain processes, network connections, loaded modules, encryption keys, and unsaved content. Acquisition can alter the system and require trusted tools and elevated privileges. Capture only within authority and with a clear purpose. Record tool-induced changes, acquisition failures, and the system state. A memory image can contain highly sensitive material unrelated to the case.","Analyze process relationships, command lines, modules, and network artifacts in context. A legitimate process name can be imitated, and a signed binary can be misused. Memory findings can corroborate disk artifacts, but volatile observations are tied to the capture time and should not be presented as a complete history."]},{title:"Attribution and anti-forensics",body:["A user-account artifact does not prove which human was present. Consider shared credentials, remote sessions, scheduled tasks, synchronization, and malware. Correlate logon events, application activity, physical access, and independent communications. Explain why the combined evidence supports or weakens the attribution hypothesis.","Deleted logs, timestamp manipulation, and unusual cleanup can be relevant, but ordinary privacy tools and system maintenance also produce similar-looking artifacts. Avoid treating every anomaly as deliberate anti-forensics. Preserve the original state, compare known-good behavior, and explain alternative causes."]}],practice:{title:"Build a local execution timeline",scenario:"A supplied fictional endpoint dataset contains a download, a process event, and an outbound connection.",steps:["Normalize timestamps and record clock uncertainty.","Link the download to the process through a stable artifact, not just filename similarity.","Compare the connection time and process relationship.","State what the sequence does and does not establish about user intent."],debrief:"A timeline becomes persuasive when artifacts independently connect the same event sequence and limitations are explicit."},quiz:["Why is a user-profile path alone weak proof of attribution?",["It contains no characters.","Accounts can be shared, compromised, or used by automated processes.","All filesystem paths are fabricated.","It proves physical presence in every case."],1,"The profile identifies an account context; linking that context to a human requires corroboration."],laws:["bsa","bnss"],sources:["cert","nist-guide","mitre"],labId:"acquisition"}),e({id:"3.9",title:"Network Forensics",minutes:15,summary:"Interpret packets, flows, and logs to reconstruct communication while respecting encryption, shared infrastructure, and collection limits.",sections:[{title:"Packets, flows, and logs",body:["A packet capture can contain headers and payloads; a flow record summarizes communication such as addresses, ports, times, and byte counts. Firewall, proxy, DNS, and authentication logs offer different views. Full payload capture is not always available, lawful, or useful. Define the question and collect the least intrusive representation that can answer it.","A connection to an IP address does not identify a website conclusively when hosting is shared or content delivery networks are involved. DNS queries can be cached, prefetched, or generated by background software. TLS encryption may hide content while leaving useful metadata. Do not infer a visited page solely from a reverse-DNS name."]},{title:"Beaconing and baseline analysis",body:["Periodic outbound connections can indicate malware command-and-control, but legitimate update checks, telemetry, and messaging applications also beacon. Examine interval regularity, jitter, destination changes, data volume, process association, and known business behavior. Compare a baseline before labeling a pattern suspicious.","A useful timeline distinguishes connection start, DNS lookup, authentication, and data transfer. Normalize time zones and account for clock drift. Record capture loss and sampling because missing packets can create misleading gaps. Flow summaries may support a pattern without proving the content or purpose of the communication."]},{title:"Collection integrity and attribution",body:["Capture at a defined observation point, document topology, filters, clock source, and capture tool settings. Hash completed capture files and restrict access because traffic can contain unrelated personal data. Live capture changes storage and may affect performance; obtain approval for material operational risks.","NAT can map many internal devices to one public address. DHCP leases, proxy authentication, endpoint telemetry, and provider records may help distinguish them. A destination, timing pattern, or ATT&CK technique label is not proof of a named attacker. Present the observation, plausible explanations, and further lawful collection needed."]}],practice:{title:"Beacon or update service?",scenario:"A host contacts the same fictional endpoint every five minutes with similarly sized requests.",steps:["Filter the supplied events by source and destination.","Calculate intervals and compare variation and byte counts.","Check the baseline and process context before classifying the activity.","Write a cautious finding and preserve the relevant source records."],debrief:"Regularity is a lead. A useful conclusion considers legitimate software and identifies evidence that would distinguish it from malicious behavior."},quiz:["Does regular beaconing alone prove malware?",["Yes, all periodic traffic is malicious.","No; legitimate services can also generate periodic connections.","Yes, if the packets use HTTPS.","Only when the public IP is shared."],1,"Beaconing requires context, baseline comparison, and corroboration before a malicious interpretation is justified."],laws:["it-act","bnss","bsa"],sources:["nist-guide","cert","mitre"],labId:"network"}),e({id:"3.10",title:"Mobile Forensics",minutes:14,summary:"Handle phones as evolving, encrypted, cloud-connected systems whose extraction labels do not guarantee completeness.",sections:[{title:"Device state and preservation",body:["Record model, identifiers, lock state, connectivity, battery, operating system, and visible time. Determine whether the device is unlocked, after first unlock, or fully locked, because these states can affect accessible data. Remote wipe and network synchronization are risks, but isolation can also change evidence and device behavior.","There is no universal airplane-mode instruction. RF isolation, power management, and supported preservation methods require a tested procedure and qualified judgment. Keep the device powered where appropriate, document actions, and avoid repeated unlock attempts. Obtain the necessary authority and consent or legal process for access."]},{title:"Extraction methods and application data",body:["Manual review, logical export, filesystem extraction, backup-based methods, and exploit-assisted techniques differ in scope and risk. A tool’s “full” extraction label may omit app data protected by separate encryption or unsupported formats. Record the exact tool, version, method, device state, and what could not be accessed.","Messages may exist in application databases, cloud backups, paired devices, and provider records. Deleted-message recovery depends on database behavior, retention, encryption, and overwriting. Preserve original databases and decode timestamps carefully. Screenshots can supplement but should not replace a reliable export when one is lawfully available."]},{title:"Location, health, and attribution",body:["Location records can originate from GPS, Wi-Fi, cellular observations, photographs, or applications. Each has different accuracy and semantics. A point on a map may represent an estimated area or a cached location, not a person’s exact movement. Health and wearable records may be synchronized and transformed by the companion app.","A phone in someone’s possession is not conclusive proof that they authored every message. Consider shared access, remote compromise, notifications, and scheduled actions. Corroborate important events with device logs, provider records, and independent context. Minimize exposure of unrelated intimate data during examination and disclosure."]}],practice:{title:"Choose a mobile preservation plan",scenario:"A complainant offers an unlocked phone containing a relevant chat and consents to a scoped export.",steps:["Record device state and the consent or authority boundary.","Compare a supported chat export with broader extraction options.","Preserve the original export, identifiers, and relevant context.","List cloud and recipient records that may require separate requests."],debrief:"A narrow supported export may be sufficient and proportionate. More invasive extraction is not automatically more reliable or lawful."},quiz:["What should an examiner record about a mobile extraction?",["Only the phone’s colour.","The method, tool version, device state, scope, and limitations.","Only whether the screen was on.","A guarantee that every deleted message was recovered."],1,"Extraction completeness depends on the device, method, access state, and application support."],laws:["bsa","bnss","dpdp"],sources:["cert","privacy","bsa"],labId:"acquisition"}),e({id:"3.11",title:"Email Forensics",minutes:15,summary:"Read headers, authentication results, and message context together to distinguish technical observations from claims about the sender.",sections:[{title:"Preserve the complete message",body:["A raw message or supported mailbox export can preserve headers, MIME structure, attachments, and encoding that a screenshot omits. Record the mailbox, folder, retrieval method, account control, and export settings. Preserve attachment hashes separately and keep the original message unchanged. Do not open suspicious attachments on an ordinary workstation.","Headers describe a processing path, often through multiple servers. The visible From address can differ from the envelope sender in Return-Path. Received lines are generally read from top to bottom as later-to-earlier hops, but untrusted portions can be forged. Message-ID and Date fields are not guaranteed proof of origin or actual sending time."]},{title:"SPF, DKIM, and DMARC",body:["SPF evaluates whether a sending path is authorized for the envelope domain, commonly reflected in Return-Path. DKIM uses a cryptographic signature over selected message content and headers; a valid signature shows that the signing domain signed the surviving signed material, not that the message is benign. DMARC evaluates identifier alignment with the visible From domain under its policy and results.","A pass does not prove that the visible sender is a trusted person. A legitimate but compromised domain can pass authentication. A fail can arise from forwarding or configuration problems, although it remains a useful warning. Inspect the actual Authentication-Results produced by a trusted receiver and understand the alignment, not just the words “pass” or “fail”."]},{title:"Fraud reconstruction and response",body:["Compare the message’s request with known business process, prior payment instructions, and independently verified contact details. Look for changed bank details, urgency, secrecy, and unusual reply routing. These are risk indicators, not a complete legal proof of cheating. Correlate mailbox audit logs, sign-in events, payment records, and recipient actions.","If compromise is suspected, preserve evidence before coordinated containment, secure accounts, revoke sessions where appropriate, and notify the relevant response team. Contact the bank through an official channel for urgent transfers. A classroom header exercise does not send email, contact a server, or test a real account."]}],practice:{title:"The urgent account change",scenario:"A message displays “Supplier Finance” but uses a different From domain and a new beneficiary account.",steps:["Read the full headers and identify From, Return-Path, and authentication results.","Explain what each pass or fail establishes and what it does not.","Verify the request using a previously known contact, not the message’s phone number.","Preserve the raw message and payment trail before changing the original evidence."],debrief:"Authentication is one layer. Payment verification and account-control evidence often decide whether the request was genuinely authorized."},quiz:["What does a valid DKIM signature establish?",["That the email is safe and truthful.","That the signing domain signed material that still verifies.","That the CEO personally wrote the message.","That no account could have been compromised."],1,"DKIM provides cryptographic integrity and domain-signature information, not a guarantee of benign intent or human authorship."],laws:["it-act","bns","bsa"],sources:["itact","cert","bsa"],labId:"email"}),e({id:"3.12",title:"Cloud Forensics",minutes:15,summary:"Investigate distributed services through tenant records, audit trails, snapshots, and provider cooperation rather than assuming access to a physical server.",sections:[{title:"Service models and evidence control",body:["In infrastructure-as-a-service, a customer may control virtual disks, snapshots, operating-system logs, and network configuration while the provider controls the physical infrastructure. Platform and software services expose different logs and exports. Identify the service model, tenant, region, account, and subscription before planning acquisition.","A cloud “disk” is a distributed abstraction. Snapshot and export mechanisms may be more practical and less disruptive than attempting physical access. Record the snapshot identifier, source volume, consistency settings, creation time, encryption context, and export process. A snapshot can be crash-consistent rather than application-consistent, affecting interpretation."]},{title:"Audit logs and identity events",body:["Control-plane logs record actions such as creating a snapshot, changing a policy, or issuing a token, while application logs record service-level events. They are not interchangeable. Examine actor identity, role, session, source context, requested action, result, and resource identifier. Service accounts and assumed roles can obscure the initiating human without additional correlation.","Cloud clocks, event delivery delays, and regional timestamps require careful normalization. Preserve the raw API response and query parameters, including pagination and filters. An export showing no events may reflect the wrong region, time range, or log source. Check retention, ingestion delay, and whether logging was enabled before the incident."]},{title:"Provider cooperation and volatile services",body:["Containers, serverless functions, and autoscaled instances can disappear quickly. Preserve configuration, images, logs, and relevant runtime observations where authorized. A running container may contain useful state, but rebuilding from a known image does not recreate every runtime change. Document what the snapshot or capture actually includes.","Ask the provider for specific records through the competent route and explain preservation urgency. A customer cannot ordinarily seize a shared physical host. Cross-border storage and provider jurisdiction affect access. Present findings with the service boundary visible: “the tenant audit log records” is more precise than an unsupported statement about the provider’s entire infrastructure."]}],practice:{title:"Reconstruct a snapshot action",scenario:"A fictional cloud audit log shows a role creating and sharing a volume snapshot.",steps:["Identify the role, session, resource, action, region, and timestamp.","Correlate the role assumption with authentication records.","Preserve the complete paginated log response and query settings.","Separate the observed API action from the identity of the human operator."],debrief:"Cloud attribution is a chain through identities, roles, sessions, and resources. One actor field is rarely the whole answer."},quiz:["Why is a cloud snapshot not always a complete forensic acquisition?",["It can never contain files.","Its consistency, scope, encryption, and service boundary may limit what it preserves.","Cloud providers do not use clocks.","It automatically includes every provider log."],1,"A snapshot represents a defined resource and state; related logs, memory, and provider records may need separate preservation."],laws:["bnss","bsa","dpdp"],sources:["nist-guide","privacy","budapest","bsa"],labId:"acquisition"}),e({id:"4.1",title:"Introduction to Digital Evidence Forensic Toolkit (DEFT)",minutes:12,summary:"Study DEFT as a forensic environment and a collection of tools—not as a magic button that makes evidence admissible.",sections:[{title:"What DEFT is and is not",body:["DEFT, the Digital Evidence and Forensic Toolkit, is a Linux-based forensic distribution associated with a suite of examination and response utilities. Depending on the release, it includes or integrates tools for acquisition, filesystem examination, recovery, memory analysis, and network investigation. DEFT and DART are related historically but should not be treated as identical product names.","Many releases are old and unsupported. Their kernels, drivers, libraries, and tool versions may not handle current hardware, encryption, or application formats. This course explains transferable workflows rather than instructing learners to deploy an obsolete distribution on a real case. An archived environment can be useful for isolated training with supplied images."]},{title:"The environment and its tools",body:["A forensic distribution packages a boot environment, utilities, dependencies, and menu launchers. The launcher does not establish that a tool is validated for the particular evidence source. Identify each tool’s actual version, input format, output behavior, and limitations. Filesystem examination, carving, memory analysis, and traffic analysis remain separate tasks requiring separate explanations.","DEFT-associated workflows may use tools such as The Sleuth Kit, Autopsy, carving utilities, and acquisition programs, but package contents vary by release. Record what is actually present rather than copying a menu list from another edition. The same caution applies to Kali: the distribution’s name is not a substitute for method validation."]},{title:"A defensible classroom workflow",body:["Use a disposable virtual machine, a synthetic image, and a written exercise objective. Keep the original image read-only and create a separate output area. Record the environment, tool versions, input hash, settings, and output hashes. Do not connect personal accounts, real evidence, or an uncontrolled network to an unsupported environment.","For an exam, explain DEFT’s role, the major workflow stages, and the need for current validation. For a practical demonstration, the browser-based acquisition and integrity labs in this course model the reasoning without pretending to perform a physical disk acquisition. A simulated hash is labelled as such; real SHA-256 calculations use the browser’s cryptographic API."]}],practice:{title:"Inspect the toolkit inventory",scenario:"An archived DEFT VM contains several versions of a carving utility.",steps:["Record the distribution and tool versions actually installed.","Match one tool to acquisition, examination, or reporting.","Identify hardware and format limitations.","Create a read-only input and separate output plan for a synthetic image."],debrief:"An inventory connects the tool to a task and version. A generic claim that “DEFT was used” does not make the examination reproducible."},quiz:["What is the safest use of an old DEFT release today?",["Connect it directly to live production evidence.","Assume every included tool is current and validated.","Use an isolated training environment and verify each tool’s limitations.","Treat its name as proof of admissibility."],2,"Archived distributions can teach concepts, but current casework requires supported methods and task-specific validation."],laws:["bsa","bnss"],sources:["cert","nist-guide","bsa"],labId:"acquisition"}),e({id:"4.2",title:"Introduction to Kali Linux Environment",minutes:12,summary:"Kali packages security and forensic utilities; safe configuration and disciplined evidence handling determine its forensic usefulness.",sections:[{title:"Purpose, releases, and tool selection",body:["Kali Linux is a Debian-based distribution maintained for penetration testing and security work, with forensic packages available. It is not exclusively a forensic distribution. The presence of a tool does not authorize its use, and a penetration-testing workflow may intentionally modify a target in ways unsuitable for evidence preservation.","Use official documentation and verified images for a lab environment. Record release, kernel, architecture, and package versions. Avoid running unsupported commands copied from unrelated tutorials. A current package may change defaults or output formats, so the report must identify the actual environment used."]},{title:"Forensic mode and write protection",body:["Kali’s forensic boot options are intended to reduce automatic mounting and use of swap in supported configurations. Verify the actual boot behavior and storage configuration; a menu label alone is not proof that no writes occurred. Software precautions differ from a validated hardware write blocker, and virtualized storage introduces another layer of configuration.","Booting a suspect computer can itself change firmware state, clocks, or other evidence. Where acquisition from the running machine is inappropriate, use an approved offline method or a controlled laboratory boot environment. Document the chosen approach and its expected effects. Never assume that a live USB leaves every component untouched."]},{title:"Isolation, privileges, and reproducibility",body:["Use synthetic data, snapshots, least privilege, and controlled networking in the classroom. Keep input evidence separate from tool output and avoid modifying the source image. Record commands or graphical settings, versions, time zone, and errors. Sensitive evidence should not be uploaded to an external service merely to make analysis easier.","Kali can support acquisition, inspection, and network analysis, but tool selection must follow the question. A password-auditing tool is not automatically appropriate for a seized device. Authority, scope, proportionality, and safety remain the examiner’s responsibility, even when a utility makes an action technically easy."]}],practice:{title:"Validate the boot assumptions",scenario:"A student says selecting “forensic mode” guarantees that the source disk cannot change.",steps:["List the assumptions behind that statement.","Check the documented behavior for the exact release.","Compare software precautions with a hardware write blocker.","Write a safer acquisition plan with verification and limitations."],debrief:"Forensic mode is a configuration aid, not an unconditional guarantee. Verify what the complete environment actually does."},quiz:["Does Kali forensic mode replace every other preservation safeguard?",["Yes, it makes all writes impossible.","No; configuration, verification, authority, and documentation still matter.","Yes, but only on laptops.","No, because Linux cannot examine evidence."],1,"The environment must be checked in context; forensic mode is not a universal write-protection guarantee."],laws:["bsa","bnss"],sources:["cert","nist-guide"],labId:"acquisition"}),e({id:"4.3",title:"Installation and Configuration of DEFT",minutes:14,summary:"Prepare an isolated, documented environment with verified installation media, controlled storage, and a repeatable test plan.",sections:[{title:"Plan before installing",body:["Choose an archived release only when the exercise requires it, obtain installation media through a trustworthy source, and verify its published checksum or signature where available. Record the source and verification result. Old installation media may contain vulnerable software; isolate it from untrusted networks and do not use it as an everyday internet workstation.","Allocate CPU, memory, and separate virtual disks for the operating system, read-only evidence, and outputs. Document the hypervisor, guest architecture, network mode, and snapshot state. A VM snapshot is useful for resetting a classroom tool environment, but it is not a substitute for preserving the original evidence exhibit."]},{title:"Configure and test the environment",body:["After installation, record the release, tool versions, time settings, storage mappings, and permissions. Confirm that the evidence input is read-only through the actual configuration and that output is written to a separate location. Avoid shared clipboards, automatic mounting, and accidental drag-and-drop into the evidence directory.","Run a known synthetic test image through the intended workflow. Confirm that the tool can read the format, that expected artifacts are recovered, and that the source remains unchanged. Record errors and unsupported features. Validation should cover the specific task rather than relying on a general claim that the distribution is “forensic”."]},{title:"Prepare a repeatable lab record",body:["Create a lab template with environment details, input identifiers and hashes, procedure, output identifiers and hashes, observations, and limitations. Use snapshots to return to a known state between exercises, but keep experiment outputs outside the disposable system disk. Explain which settings are necessary to reproduce the result.","Do not install random packages during an examination without recording the change. Dependencies and updates can alter behavior. If a tool fails, preserve the error and choose a documented alternative rather than repeatedly modifying the source. The browser labs here provide the safe conceptual sequence; they do not claim to install or emulate an entire Linux distribution."]}],practice:{title:"Write the VM preparation checklist",scenario:"You are preparing an archived forensic distribution for a synthetic filesystem exercise.",steps:["Record the media source and verification result.","Separate the OS, evidence, and output storage.","Set an isolated network mode and document time settings.","Run a known test image and save the environment configuration."],debrief:"A reproducible setup makes tool behavior easier to evaluate and prevents an avoidable mix-up between evidence and experiment output."},quiz:["Where should tool output be written in a controlled forensic lab?",["Into the original evidence file.","To a separate, documented output location.","Over the source directory entry.","To an unknown public upload service."],1,"Separating inputs from outputs protects the original and makes transformations traceable."],laws:["bsa","bnss"],sources:["cert","nist-guide"],labId:"acquisition"}),e({id:"4.4",title:"Forensic Imaging and Data Acquisition",minutes:16,summary:"Create a documented representation of the source, verify what you acquired, and explain any limits on completeness or repeatability.",sections:[{title:"Image formats and source scope",body:["A raw bit-stream image represents acquired sectors in sequence. Formats such as E01 can add metadata, compression, segmentation, and integrity checks; Ex01 extends the format family. The file extension alone does not tell you what was acquired. Record the source device, range, sector size, hidden areas considered, tool, settings, and any inaccessible regions.","A logical collection of files differs from a physical image of storage. The former may omit deleted content and filesystem structures; the latter may still omit host-protected areas or inaccessible flash translation layers. State the scope precisely. For mobile and cloud sources, use the method appropriate to the service rather than forcing a disk-image analogy."]},{title:"Acquisition and hash workflow",body:["Prepare and verify destination storage, use a suitable write-protection method, and record identifiers before acquisition. Calculate and retain the source or acquired-data hash as the method permits. Record bad sectors, read errors, retries, and interruptions. After acquisition, verify the image or extracted stream according to the format and document exactly what the hash covers.","A container hash can differ from the underlying data hash because metadata or compression changed. Do not compare unrelated values and call the result a failure. For a live source that continues changing, explain why a stable full-source hash may be unavailable and what integrity checks support the captured material."]},{title:"Working copies and quality control",body:["Preserve the master image under controlled access and examine a verified working copy. Record every derived export and its relationship to the parent image. If the image format is converted, verify the underlying data where possible and preserve the original container. A successful copy operation is not enough without an integrity check.","Quality control includes capacity planning, tool validation, error review, and a second-person check of identifiers. A hash collision is not a practical substitute for explaining a mismatch caused by the wrong source or altered output. The acquisition report should let a reviewer understand both the technical result and its evidential limits."]}],practice:{title:"Plan a 500 GB acquisition",scenario:"A laptop disk contains bad sectors, and the available destination is nearly full.",steps:["Confirm source and destination capacity and identifiers.","Choose a format and error-handling strategy appropriate to the tool.","Record acquisition hashes, errors, and inaccessible ranges.","Verify a working copy and preserve the master before analysis."],debrief:"An acquisition with documented read errors may still be useful, but the missing ranges must be visible in the report. Silent omission is not acceptable."},quiz:["Why distinguish an image-container hash from an underlying-data hash?",["They may cover different bytes and metadata.","They always prove different crimes.","One is not a cryptographic value.","The distinction is irrelevant to verification."],0,"A valid comparison must use the same representation and scope; container metadata can change its hash."],laws:["bsa","bnss"],sources:["cert","nist-guide","bsa"],labId:"hash"}),e({id:"4.5",title:"Disk Analysis using DEFT",minutes:14,summary:"Use filesystem metadata, file content, and application artifacts together to answer a scoped investigative question.",sections:[{title:"Orient the examination",body:["Verify the working image and identify partitions, filesystem types, volume identifiers, and relevant time settings. A disk may contain several operating systems, encrypted volumes, or recovery partitions. Record which areas are accessible and which are not. The Sleuth Kit can expose filesystem structures, while a graphical interface may organize the same underlying information differently.","Define search terms, date ranges, and artifact categories from the investigative question. Broad keyword searches can produce irrelevant private material and false matches. Document the terms and explain why they were selected. Preserve significant results with their source paths and image offsets or equivalent identifiers."]},{title:"Files, metadata, and relationships",body:["Examine allocated files, deleted entries where recoverable, and relevant application databases. Compare filesystem timestamps with timestamps embedded in documents or messages. A copied file may retain an older embedded creation time while receiving a new filesystem time. Neither value should automatically be treated as the true human authoring time.","Link artifacts through stable identifiers and context: a browser download record, a file hash, a shortcut, and an application log may support a sequence. Filename similarity alone is weak. Where a tool decodes a database, record the version and verify important records against the original data or a second method."]},{title:"Interpret and report the result",body:["Separate what the filesystem records from what the examiner infers. A deleted directory entry does not identify who deleted it, and a file in a user directory does not prove that the user knowingly placed it there. Consider synchronization, temporary files, automated downloads, and shared access.","Export relevant findings into controlled presentation copies with hashes and source references. Explain the tool settings, time normalization, and limitations. A readable timeline is useful only if each event points back to an artifact. The final report should answer the question rather than overwhelm the reader with every recovered filename."]}],practice:{title:"Find the invoice’s context",scenario:"A synthetic image contains an invoice, a browser download record, and a shortcut with different timestamps.",steps:["Verify the image and record the filesystem context.","Compare the three artifacts and their timestamp semantics.","Use hashes and source identifiers to link the records.","Write a cautious sequence of events with alternative explanations."],debrief:"A coherent timeline comes from understanding artifacts, not sorting every timestamp and assuming the order proves intent."},quiz:["Which is the strongest way to link a downloaded file to a browser record?",["Only a similar filename.","Relevant identifiers, hashes, paths, and corroborating timestamps.","The largest file on the disk.","The examiner’s intuition."],1,"Multiple consistent identifiers and contextual records provide a more defensible link than a name alone."],laws:["bsa","bnss"],sources:["cert","nist-guide","bsa"],labId:"hash"}),e({id:"4.6",title:"Recovery of Deleted Files and Artifacts",minutes:14,summary:"Deleted, hidden, and inaccessible are different states. Recovery depends on storage behavior, filesystem context, and encryption.",sections:[{title:"What deletion actually changes",body:["A filesystem may mark an entry as unused while leaving some content or metadata recoverable. Subsequent writes, journal behavior, cleanup, and application maintenance can change that state. On flash storage, TRIM and garbage collection may erase underlying pages independently of the visible filesystem operation. Do not promise recovery merely because deletion was recent.","Hidden files can be ordinary application data, protected system files, or intentionally concealed material. A hidden attribute is not proof of wrongdoing. Alternate data streams, unusual extensions, archive containers, and cloud placeholders require format-aware examination rather than a single “show hidden files” action."]},{title:"Filesystem recovery and carving",body:["Filesystem-aware recovery uses surviving entries and metadata, which can preserve names and paths. Signature-based carving searches for recognizable file structures when those entries are unavailable. Fragmentation, embedded files, encryption, and damaged headers complicate carving. A carved file may be incomplete or combine unrelated fragments if the method is unsuitable.","Work from the preserved image and record the tool, version, settings, source ranges, and recovered output hashes. Validate important results by opening them in a safe viewer or checking internal structure. Do not execute recovered programs. Compare with backups, cloud versions, or message attachments where lawful and available."]},{title:"Explain failures and attribution limits",body:["A recovered file’s presence in unallocated space does not prove who created, used, or deleted it. Seek corroborating application artifacts, account records, and independent context. Explain whether timestamps came from surviving metadata, embedded content, or tool assumptions. Do not silently restore a filename that the recovery method could not actually establish.","Record failed recovery and its likely causes without overstating them. “The tool did not recover a valid file” is different from “no such file ever existed”. A careful negative finding can guide further collection, such as a provider export or backup request, without turning absence into proof."]}],practice:{title:"Choose a recovery route",scenario:"An encrypted SSD image contains a deleted-entry reference but no readable file content.",steps:["Distinguish metadata recovery from content recovery.","Identify encryption, TRIM, and overwriting as possible limits.","Check lawful backups or cloud versions rather than forcing a result.","Document the failed method and the evidence still available."],debrief:"Recovery is conditional. Understanding why a method failed is part of a defensible examination."},quiz:["Which factor can make deleted-data recovery from an SSD difficult?",["The screen brightness.","TRIM and flash garbage collection.","The desktop wallpaper alone.","The number of folders in the user interface."],1,"Flash-management behavior can erase or relocate underlying data independently of filesystem expectations."],laws:["bsa","bnss"],sources:["cert","nist-guide"],labId:"hash"}),e({id:"4.7",title:"Memory and Log Analysis",minutes:15,summary:"Combine volatile state with persistent records to reconstruct events and test whether a suspicious process or logon was actually active.",sections:[{title:"Memory acquisition and interpretation",body:["Memory can reveal running processes, loaded modules, network connections, injected regions, and other state absent from disk. Acquisition requires a suitable tool, privileges, and a documented risk decision. The tool changes the machine while collecting evidence. Preserve the output, record the profile or symbol requirements, and explain incomplete or failed analysis.","A memory-analysis framework such as Volatility can enumerate artifacts using operating-system structures. Version and symbol mismatches can produce misleading results. A process name is not a validated identity; examine path, parent-child relationships, command line, loaded components, and corroborating telemetry. Sensitive content in memory must be access-controlled."]},{title:"Log semantics and event reconstruction",body:["Windows Security, System, Application, and Sysmon logs answer different questions. Event IDs must be interpreted with provider, version, and configuration in mind. A logon event does not automatically prove interactive human presence; network, service, and remote logon types differ. Linux authentication, service, audit, and application logs similarly require context.","Build a timeline using event time, ingestion time, and acquisition time separately. Check clock drift, time zones, log forwarding delays, and missing sequences. A cleared log may be relevant, but rotation and administrative maintenance can also remove records. Preserve the original log files and document any parsing or conversion."]},{title:"Correlation and uncertainty",body:["Correlate memory observations with disk artifacts and network records. A process seen in RAM may explain a connection that disk logs alone cannot. Conversely, a persistent service configuration may explain a process that initially looked unusual. Seek independent support before concluding malicious execution or deliberate log tampering.","Report the capture time and the limits of historical inference. A memory image is a snapshot, not a complete recording of everything that happened. A log timeline is limited by what was configured, retained, and successfully collected. Clear separation between observation and interpretation keeps the reconstruction credible."]}],practice:{title:"Explain a logon event",scenario:"A supplied log records a network logon followed by a service process and an outbound connection.",steps:["Identify the logon type and account context.","Compare the process and connection times with clock uncertainty.","Check whether scheduled maintenance offers a plausible baseline explanation.","Write a finding that distinguishes account activity from human attribution."],debrief:"Event correlation can establish a sequence without establishing intent. The log’s semantics determine how far the conclusion can go."},quiz:["Why is a memory image insufficient to reconstruct the entire incident history?",["It captures state at a particular time and may omit earlier activity.","It contains only photographs.","It cannot be hashed.","It always proves every process is malicious."],0,"Memory is a time-specific observation; persistent logs and other evidence are needed for a broader history."],laws:["bsa","bnss"],sources:["cert","nist-guide","mitre"],labId:"network"}),e({id:"4.8",title:"Network Traffic Analysis using DEFT Tools",minutes:13,summary:"Use packet and flow utilities to answer defined questions, preserving capture context and avoiding unsupported content or identity claims.",sections:[{title:"Prepare the traffic dataset",body:["A supplied PCAP or PCAPNG can be examined with Wireshark or command-line utilities such as tcpdump; Zeek can produce structured connection summaries. DEFT package availability varies by release. Record the actual tool and version, input hash, capture interface if known, filters, and time settings. A display filter changes what is shown, not necessarily what the original capture contains.","Start with endpoints, protocols, capture duration, and missing-packet indicators. Understand whether the capture came from a host, span port, tap, or proxy. Each observation point sees a different part of the path. Checksum offloading can create apparent errors on a local capture; investigate before treating them as evidence of corruption."]},{title:"Follow streams and reconstruct events",body:["Conversation filters and stream following can make a protocol exchange readable, but exported objects are new derived files. Hash and identify them separately. Encrypted traffic may expose metadata without content. Do not bypass encryption or infer a page’s contents from a domain name alone. Preserve the relevant packet numbers and original capture.","For DNS, compare queries, responses, transaction identifiers, and timing. For HTTP, examine method, host, path, status, and content type where available. For periodic connections, measure intervals and variation. A useful finding explains what was observed and whether a normal service could produce the same pattern."]},{title:"Report beyond the tool screenshot",body:["A screenshot of a packet list is not a complete analysis. State the filter, time basis, endpoints, relevant packets, interpretation, and limitations. If NAT or DHCP prevents device attribution, say so and identify the lawful records needed. Avoid publishing unrelated payloads or personal information in a teaching report.","Export only necessary derived artifacts and document their relationship to the capture. Where a second tool confirms a finding, explain what it checked. The course’s network lab uses synthetic records and never scans or contacts the displayed addresses. This keeps the exercise reproducible and safe."]}],practice:{title:"Explain the capture boundary",scenario:"A synthetic capture shows periodic connections from a NAT address to a shared hosting endpoint.",steps:["Record the observation point and filter.","Measure the intervals and compare payload sizes.","Identify why the public address may represent several devices.","Write a source-linked finding and request only the records needed for attribution."],debrief:"Traffic analysis can establish a communication pattern while leaving device and human attribution unresolved."},quiz:["What does a display filter do?",["Deletes all other packets from the original capture.","Changes which packets are displayed for analysis.","Decrypts every protocol.","Identifies the human sender."],1,"A display filter controls the view. The underlying capture should remain preserved and unchanged."],laws:["it-act","bsa","bnss"],sources:["cert","nist-guide","mitre"],labId:"network"}),e({id:"4.9",title:"Preparation of Forensic Reports",minutes:12,summary:"Turn technical work into a clear, reproducible, source-linked account that a court or another examiner can evaluate.",sections:[{title:"Essential report components",body:["Identify the instructing authority, examiner, scope, dates, exhibits, and question. Record acquisition and examination methods, tool versions, relevant settings, hashes, and limitations. Present findings in a logical order and connect each material conclusion to a source. Distinguish facts supplied by others from facts the examiner directly verified.","Use appendices for the exhibit register, custody history, hash table, timeline, and detailed technical output. Define acronyms and explain specialized terms. The reader should understand why a result matters without having to trust an unexplained tool label. A concise executive summary should remain faithful to the body of the report."]},{title:"Writing defensible conclusions",body:["Use calibrated language such as observed, consistent with, insufficient evidence, or cannot be determined. Explain the basis for the chosen level of confidence. Avoid legal conclusions reserved to the court, such as declaring a person guilty. A forensic examiner can describe artifacts and technical implications; proving the offence requires the wider evidential record.","Record contrary evidence and material limitations. If a clock offset is unknown, a tool could not decode an application, or an acquisition had read errors, disclose it. A report is not persuasive because it hides uncertainty. It is persuasive because the reader can see how uncertainty was handled."]},{title:"Review and controlled issue",body:["Check every exhibit reference, hash, timestamp, calculation, and quotation. Technical review should test the reasoning as well as spelling. Preserve drafts and corrections under the applicable disclosure and records policy. When issuing a supplement, explain what changed and why rather than silently replacing the earlier report.","Create redacted disclosure copies where necessary without altering the original. For classroom PDF export, this course includes the lesson, practical exercise, sources, and optional answer explanations. A real forensic report additionally requires the actual exhibit records, signed documentation, and applicable procedural compliance."]}],practice:{title:"Write a finding template",scenario:"A recovered message is linked to a mailbox export but not yet to a human sender.",steps:["State the observed artifact and its source.","Describe the method and verification.","Explain the attribution limitation.","Draft a conclusion that avoids declaring guilt."],debrief:"A precise finding can be useful without exceeding the evidence. Clear limits help the investigator decide what to collect next."},quiz:["Which belongs in a defensible forensic report?",["Only conclusions that support the prosecution.","Methods, sources, findings, limitations, and reproducible references.","Unsupported claims about the suspect’s character.","A tool name with no version or settings."],1,"The reader must be able to evaluate the process and the basis of the conclusions."],laws:["bsa","bnss"],sources:["bsa","cert","nist-guide"],labId:"certificate"}),e({id:"4.10",title:"Digital Evidence Presentation Techniques",minutes:11,summary:"Make complex evidence understandable with accurate timelines, relationship diagrams, and carefully contextualized excerpts.",sections:[{title:"Choose a visual for the question",body:["A timeline communicates sequence; a relationship diagram communicates links; a table communicates exact values and sources. Choose the simplest form that answers the question. Label time zones, uncertainty, inferred relationships, and source identifiers. Avoid decorative graphics that imply certainty or causation where only association was observed.","For a payment-fraud case, place the original instruction, account-change request, authentication event, and transfer on one carefully sourced timeline. Show missing intervals rather than drawing an uninterrupted line through them. A visual should make the evidence easier to inspect, not replace the underlying records."]},{title:"Excerpts, redaction, and context",body:["A short chat excerpt can be readable but misleading if surrounding messages are omitted. Identify the excerpt, provide the full source under controlled access, and explain selection criteria. Redact unrelated personal information in presentation copies while preserving the original. Mark transformations so the audience does not confuse a demonstrative aid with the evidence itself.","Hash tables should identify exactly which file or output each value covers. Screenshots should include enough context to locate the source, but not expose passwords or unrelated data. For printed material, use legible type, page numbers, exhibit references, and captions that remain understandable in black and white."]},{title:"Explain without overwhelming",body:["Introduce the question, then the key finding, then the supporting artifacts. Define technical terms in ordinary language. Use an analogy only after stating its limits: a hash is like a fingerprint for comparison, but it does not identify a human sender. Invite the audience to inspect the source references.","Check every visual against the report before presentation. An attractive diagram with an unsupported edge can create a false impression. The course’s printable notes preserve source links and explanations so learners can review the reasoning away from the interactive interface."]}],practice:{title:"Design a one-page evidence timeline",scenario:"You have four events with known times and one uncertain attribution.",steps:["Place the known events in time order with sources.","Mark the uncertain attribution explicitly.","Choose a table or timeline that stays readable in print.","Add a caption explaining what the visual does not prove."],debrief:"A good presentation makes uncertainty visible and traceable rather than hiding it behind visual polish."},quiz:["What should a relationship diagram distinguish?",["Only colours, with no labels.","Observed links, inferred links, and their sources.","The examiner’s favorite hypothesis only.","The price of each forensic tool."],1,"Labelled relationships and source references let the audience evaluate what the diagram actually establishes."],laws:["bsa"],sources:["bsa","cert"],labId:"certificate"}),e({id:"4.11",title:"Appreciation and Evaluation of Digital Evidence",minutes:12,summary:"Evaluate the whole evidential record: reliability, relevance, corroboration, alternatives, and the burden of proof.",sections:[{title:"Ask what the evidence proves",body:["For each item, identify the proposition it supports. A preserved email may prove that a message existed in a mailbox, while payment records may show a transfer. Neither automatically proves who controlled the account or intended the result. Build a chain of propositions and identify the weak links rather than treating “digital evidence” as one indivisible category.","Consider source reliability, acquisition integrity, interpretation, and context. A valid hash supports comparison; a competent custodian supports provenance; an application log may support an event. Different weaknesses require different remedies. More files do not necessarily mean stronger proof if they are duplicates or irrelevant."]},{title:"Corroboration and contrary evidence",body:["Independent sources are more valuable than repeated copies of the same claim. Compare endpoint logs, provider records, bank references, and witness accounts while noting their different time bases and scopes. A contradiction may reveal a clock error, a missing event, a false statement, or an incorrect assumption.","Test the defense or alternative explanation fairly. Shared access, compromised credentials, scheduled activity, and business-process failure may explain an artifact. The burden of proof remains a legal question, not a threshold in a forensic tool. An examiner should not fill evidential gaps with personal confidence."]},{title:"From technical finding to legal evaluation",body:["Admissibility, authenticity, and weight are distinct. A record may be admitted but carry little weight because its source is unclear. Another may be highly informative but require further proof of lawful collection or certification. The court evaluates the record in the context of the applicable law and the whole case.","Prepare a balanced evidence matrix with proposition, source, support, limitation, and corroboration. This helps counsel and investigators identify what remains to be proved. Avoid presenting a probability generated by a model as the probability that the accused committed the offence; the two questions are fundamentally different."]}],practice:{title:"Find the weakest link",scenario:"A case combines a matching hash, a shared-account login, and a bank transfer.",steps:["Write the proposition supported by each item.","Identify where account activity is being converted into human attribution.","Seek independent evidence for that link.","Explain why the hash does not cure the attribution gap."],debrief:"Strong integrity at one stage cannot compensate for an unsupported inference at another. Evaluate the chain proposition by proposition."},quiz:["Why are independent corroborating sources valuable?",["They eliminate every possible error.","They can test the same proposition from different origins.","They always contain identical timestamps.","They make legal procedure unnecessary."],1,"Independent sources can support or challenge a proposition more meaningfully than repeated copies of one record."],laws:["bsa","bnss"],sources:["bsa","anvar","nist-guide"],labId:"certificate"}),e({id:"4.12",title:"Courtroom Presentation and Expert Testimony",minutes:13,summary:"An expert assists the court with specialist reasoning, stays within expertise, and makes methods and limitations understandable.",sections:[{title:"The expert’s role and preparation",body:["BSA section 39 addresses opinions of persons specially skilled in relevant fields, while the old Evidence Act section 45 played the corresponding role. The facts supporting the opinion and the expert’s qualifications matter. Expert status does not make every assertion true, and the expert should not decide the accused’s guilt.","Prepare by reviewing the report, underlying exhibits, methods, limitations, and relevant professional guidance. Be able to explain why a method was chosen, how it was validated, what changed during acquisition, and what another examiner could verify. Distinguish your own observations from information supplied by investigators or third-party tools."]},{title:"Explain, qualify, and acknowledge limits",body:["Use plain language and a small number of well-supported visuals. Define technical terms, identify the source of each important fact, and explain the difference between consistency and conclusive proof. If a question moves beyond your expertise or the examined material, say so. A careful “I cannot determine that from this evidence” can be the most accurate answer.","Do not exaggerate tool reliability or claim a zero error rate without a defensible basis. Explain known errors, alternative explanations, and material missing data. Where the law requires a certificate or particular witness, technical expertise alone does not replace that requirement. Coordinate with counsel on procedure without becoming an advocate for a party."]},{title:"Professional independence and updates",body:["The duty is to assist the court, not to win the case. Maintain independence, disclose material limitations, and correct an opinion if new evidence changes it. Keep a clear record of supplements and the reason for revision. Do not allow cross-examination pressure to turn a qualified conclusion into an unsupported absolute.","Protect sensitive exhibits during presentation and follow the court’s directions for access, redaction, and return. After testimony, preserve the report and relevant notes under the applicable retention process. The learning goal is not theatrical confidence; it is a transparent account that remains reliable when questioned."]}],practice:{title:"Answer the difficult question",scenario:"Counsel asks: “Your tool says the file was deleted. Can you swear the accused deleted it?”",steps:["Separate the filesystem observation from human attribution.","Explain the tool’s role and the relevant limitations.","Identify evidence that would be needed for attribution.","Give a concise, neutral answer without speculation."],debrief:"A strong expert answer explains what is known, how it is known, and what the evidence cannot establish."},quiz:["What should an expert do when asked beyond the examined evidence?",["Guess confidently.","State the limitation and remain within supported expertise.","Declare the accused guilty.","Hide missing data."],1,"Expert credibility depends on transparent limits and independence, not certainty on every question."],laws:["bsa","iea"],sources:["bsa","iea","cert"],labId:"certificate"}),e({id:"5.1",title:"Introduction to Cyber Threat Intelligence",minutes:11,summary:"Cyber threat intelligence is decision support about adversaries, capabilities, and risk—not an indiscriminately collected list of bad IP addresses.",sections:[{title:"From data to actionable intelligence",body:["Threat intelligence is analyzed information that helps a decision-maker understand and act on cyber risk. Raw logs, indicators, incident reports, and actor profiles become intelligence when their relevance, reliability, and implications are evaluated. A list of domains without context may support blocking, but it does not explain the actor, campaign, or business risk.","Strategic intelligence supports leadership and policy; operational intelligence supports campaigns and defensive priorities; tactical intelligence describes techniques and behaviors; technical intelligence includes indicators and detection details. These categories overlap. The product should match its audience rather than giving every reader the same technical feed."]},{title:"Know the consumer and the decision",body:["A security operations analyst may need a detection rule with validation guidance. An incident responder may need likely persistence mechanisms. A finance leader may need exposure and mitigations. Begin with the decision, required confidence, timeframe, and acceptable action. Intelligence that cannot influence a decision is often just additional noise.","Describe the threat actor, capability, infrastructure, motivation, victimology, and observed behavior separately. A shared tool does not prove shared membership. Use confidence labels and source references. The MITRE ATT&CK knowledge base can organize observed techniques, but a technique label is not attribution to a named group."]},{title:"Reliability, sharing, and legal handling",body:["Distinguish source reliability from information credibility. A normally reliable source can repeat an unverified claim. Record whether an observation is confirmed, reported, inferred, or unknown. Sharing frameworks such as STIX, TAXII, and MISP can help structure exchange, but they do not remove confidentiality, privacy, or licensing obligations.","Threat intelligence can contain personal data, victim information, or sensitive infrastructure details. Use access controls and sharing agreements. Avoid publishing indicators that would expose victims or ongoing operations. A useful intelligence product states its date, scope, confidence, and recommended validation rather than presenting a feed as permanent truth."]}],practice:{title:"Write a priority intelligence requirement",scenario:"A university is concerned about credential phishing during admissions.",steps:["Identify the decision-maker and the decision to support.","Define the relevant accounts, period, and threat behavior.","Choose an intelligence product and confidence requirement.","Specify how the result will be validated and shared safely."],debrief:"A requirement tied to a real decision produces focused collection and a usable result."},quiz:["What makes threat information actionable?",["A long list of indicators without context.","Relevance to a decision, evaluated sources, and usable guidance.","The most alarming headline.","A claim of certainty with no evidence."],1,"Actionable intelligence connects evaluated information to an audience, decision, and appropriate response."],laws:["it-act","dpdp"],sources:["first","mitre","nist-csf"],labId:"ai"}),e({id:"5.2",title:"Threat Intelligence Lifecycle",minutes:13,summary:"Make intelligence repeatable through direction, collection, processing, analysis, dissemination, and feedback.",sections:[{title:"Direction and collection",body:["Define priority requirements, scope, assumptions, and deadlines. Identify gaps in current knowledge and choose sources that can answer the question. Sources may include internal telemetry, incident reports, public advisories, provider notices, and carefully governed sharing communities. A collection plan should record authority, handling restrictions, and expected value.","Avoid collecting everything because storage is cheap. Excess data increases privacy risk and analyst workload. For each source, record origin, access method, time coverage, reliability, and limitations. An internal authentication log and a public actor report answer different questions and should not be treated as interchangeable."]},{title:"Processing and analysis",body:["Normalize formats, timestamps, identifiers, and confidence labels without losing the original record. Deduplicate indicators and preserve relationships. Translate raw observations into a form suitable for analysis while recording transformations. A normalized domain should not accidentally become a claim that the domain is malicious.","Evaluate hypotheses about campaigns, targeting, and behavior. Compare new observations with existing knowledge and look for disconfirming evidence. The Diamond Model can organize adversary, capability, infrastructure, and victim relationships; ATT&CK can describe techniques. Neither model removes the need for source evaluation or causal reasoning."]},{title:"Dissemination and feedback",body:["Deliver the right product to the right audience in a usable format and within the decision window. Include key judgments, evidence, confidence, recommended actions, and expiry or review dates. Separate intelligence from operational instructions that require additional authorization. A suggested containment action is not itself permission to execute it.","Ask whether the product changed a decision, improved detection, or reduced uncertainty. Track false positives, missed threats, and stale indicators. Feed those results into new requirements and source evaluation. A lifecycle without feedback becomes a publication pipeline rather than a learning process."]}],practice:{title:"Run a miniature intelligence cycle",scenario:"A suspicious login pattern appears in a fictional university dataset.",steps:["Define one priority question and collect the relevant synthetic records.","Normalize timestamps and evaluate the source.","Compare credential theft with a legitimate travel or configuration change.","Deliver a short assessment and define one feedback measure."],debrief:"The cycle is iterative. Feedback can reveal that the initial requirement was too broad or that a source was less reliable than assumed."},quiz:["What is the purpose of the feedback stage?",["To delete all earlier assessments.","To improve requirements, sources, and products using observed outcomes.","To guarantee that every alert is correct.","To replace analysis with automated sharing."],1,"Feedback turns intelligence into a learning process and helps measure whether it supported better decisions."],laws:["it-act","dpdp"],sources:["first","mitre","nist-csf"],labId:"ai"}),e({id:"5.3",title:"Threat Hunting and Threat Analysis",minutes:14,summary:"Hunting proactively tests whether suspicious behavior is present, using hypotheses, baselines, and evidence rather than waiting for an alert.",sections:[{title:"Hypothesis-driven investigation",body:["A hunt begins with a testable proposition, such as whether a suspicious authentication pattern indicates token misuse in a defined environment. Identify the expected observations, required telemetry, normal baseline, and conditions that would disprove the hypothesis. A vague instruction to “find hackers” does not provide a useful scope.","Hunting differs from alert triage and incident response, although they overlap. Triage evaluates an existing alert; hunting searches for behavior that may not have triggered one; response contains and recovers from an identified incident. Define the activity and authority so a hunt does not become an uncontrolled intrusive test."]},{title:"Behavior, indicators, and analytical models",body:["The Pyramid of Pain illustrates that some adversary behaviors are harder to change than simple hashes or IP addresses. It is a conceptual model, not a numerical law. Focus on reliable behaviors and contextual combinations rather than treating every technique match as malicious. ATT&CK can help express what was observed and where visibility is missing.","Use baselines for accounts, processes, destinations, and administrative actions. Look for sequences: unusual login, new token, changed mailbox rule, and data access. A single event may be benign; a corroborated sequence may justify escalation. Record the query, dataset, time range, and false-positive considerations."]},{title:"From hunt to validated outcome",body:["A hunt can find malicious activity, benign anomalies, or visibility gaps. All three can be useful. Validate important findings before containment that could disrupt legitimate services. Preserve the relevant records and hand off to incident response with a clear account of what is known and unknown.","Measure coverage, repeatability, validation quality, and decision impact rather than only counting alerts. Convert a successful hunt into a tested detection or improved control where appropriate. Document why a hypothesis was rejected and what data would improve the next hunt. Avoid retrospective claims that the hunt proved every absent threat."]}],practice:{title:"Design a token-misuse hunt",scenario:"A fictional tenant has sign-in logs, token events, and mailbox-rule changes.",steps:["Write a hypothesis and an innocent alternative.","Define the accounts, time window, and required fields.","Correlate events and record missing telemetry.","Classify the outcome as confirmed, benign, or unresolved with next steps."],debrief:"A good hunt produces a defensible answer or a clearly identified visibility gap—not a predetermined accusation."},quiz:["What is a valid outcome of a threat hunt?",["Only a confirmed attacker.","A benign explanation or a documented visibility gap.","A guaranteed conviction.","An untested detection deployed permanently."],1,"Hunting tests hypotheses. Disproved hypotheses and missing telemetry are useful results when documented."],laws:["it-act","bnss"],sources:["mitre","first","nist-ir"],labId:"network"}),e({id:"5.4",title:"Cyber Warfare: Concept and Dimensions",minutes:13,summary:"Cyber operations can support state strategy, but not every hostile cyber operation is legally an act of war.",sections:[{title:"Concepts and strategic purposes",body:["Cyber warfare is a contested concept involving state or organized armed-conflict uses of cyber capabilities. Operations may support espionage, disruption, deception, preparation, or effects against military and civilian systems. The strategic purpose and context matter. Theft of government information, criminal ransomware, and an armed attack raise different legal questions.","Cyber operations can affect physical systems, communications, logistics, and public confidence. They may accompany conventional operations or occur below thresholds that states characterize differently. Avoid assuming that a sophisticated attack is necessarily state-sponsored or that a state-linked actor operates under direct official control."]},{title:"International-law thresholds",body:["The law on use of force, armed attack, sovereignty, non-intervention, and international humanitarian law involves distinct tests and continuing debate. UN Charter Articles 2(4) and 51 are relevant reference points, but a cyber incident’s legal characterization depends on its circumstances, effects, attribution, and applicable law. A temporary website outage is not automatically an armed attack.","Where international humanitarian law applies, distinction, proportionality, and precautions are central. Dual-use infrastructure creates difficult factual and legal questions. The Tallinn Manual is an academic analysis, not a treaty or universally binding code. Present contested interpretations as contested rather than converting expert commentary into settled law."]},{title:"Attribution and strategic communication",body:["Attribution can involve technical infrastructure, operational behavior, organizational links, and political judgment. Malware reuse, language settings, and routing are weak grounds when considered alone. States may rely on classified information that cannot be fully reproduced by an independent analyst. Distinguish a public attribution claim from evidence presented in a court.","Resilience, clear responsibilities, tested recovery, civil-military coordination, and responsible communication support national security. A classroom case should examine facts, uncertainty, and legal thresholds before choosing labels. The Stuxnet case in this course illustrates cyber-physical effects without presenting every disputed attribution detail as established fact."]}],practice:{title:"Classify without exaggeration",scenario:"A fictional government service suffers a disruptive cyber operation during a diplomatic crisis.",steps:["List the observed effects and affected functions.","Separate technical attribution from political responsibility.","Identify which legal threshold requires specialist analysis.","Write a neutral assessment with uncertainty and response priorities."],debrief:"Strategic context can inform a question, but it does not replace the evidence needed to characterize an operation under international law."},quiz:["Does every state-linked cyber operation legally constitute an armed attack?",["Yes, by definition.","No; the circumstances, effects, attribution, and applicable legal tests matter.","Yes, if malware is used.","No, because cyber operations cannot have physical effects."],1,"Cyber operations vary widely. Legal characterization requires a fact-specific analysis, not a technology label."],laws:["it-act","international"],sources:["stuxnet","nist-csf","budapest"]}),e({id:"5.5",title:"Cyber Terrorism and National Security",minutes:12,summary:"Distinguish terror-related cyber conduct from ordinary cybercrime, hacktivism, espionage, and lawful dissent.",sections:[{title:"The legal definition matters",body:["IT Act section 66F addresses specified acts with intent to threaten India’s unity, integrity, security, or sovereignty, or to strike terror, using the means and conditions stated in the provision. Unauthorized access or damage alone does not establish the full offence. BNS section 113 contains a separate terrorism framework with its own ingredients and procedural implications.","A politically motivated website defacement is not automatically cyber terrorism. Examine the intended and actual effects, target, means, and statutory wording. Conversely, a serious attack on critical infrastructure may require analysis beyond ordinary fraud or mischief. Avoid sensational labels that prejudge the evidence or dilute the legal definition."]},{title:"Critical infrastructure and cascading effects",body:["Critical sectors can depend on interconnected digital and physical systems. A disruption may cascade through power, communications, transport, finance, and health services. Identify dependencies, safety implications, and recovery priorities. Section 70 of the IT Act concerns protected-system declarations; not every important website is automatically a protected system under that provision.","National security preparedness includes sectoral coordination, exercised response plans, backups, supply-chain risk management, and clear public communication. Technical controls should be paired with human procedures and legal authority. Overcollection of unrelated personal data is not justified merely by invoking national security."]},{title:"Investigation with safeguards",body:["Preserve evidence of intent, coordination, target selection, and effects where relevant. A suspect’s speech or association does not by itself prove a terrorist act. Apply the statutory elements and constitutional safeguards, and distinguish intelligence assessments from admissible proof. Special procedures require careful legal review.","Coordinate victim protection, service continuity, and evidence preservation. Public statements should avoid unsupported attribution and unnecessary disclosure of sensitive infrastructure details. After the incident, review dependencies and controls rather than assuming that a single arrest or takedown eliminates systemic risk."]}],practice:{title:"Apply the threshold carefully",scenario:"A fictional group defaces a public information page and separately threatens a safety-critical control system.",steps:["Separate the two sets of conduct and evidence.","Identify the statutory ingredients for each candidate offence.","Assess safety and critical-infrastructure dependencies.","State what evidence of intent and effects is still missing."],debrief:"The same investigation can contain different conduct with different legal thresholds. A single “terror” label obscures that distinction."},quiz:["What is necessary before calling an incident cyber terrorism?",["A political slogan only.","Analysis of the applicable statutory elements and supporting evidence.","Any website defacement.","Use of an encrypted connection."],1,"The label depends on defined legal ingredients, not the attacker’s chosen label or the mere use of a computer."],laws:["it-act","bns"],sources:["itact","bns","constitution","nist-csf"]}),e({id:"5.6",title:"State-Sponsored Cyber Attacks",minutes:13,summary:"Study advanced operations through intrusion paths, supply-chain trust, and carefully qualified attribution.",sections:[{title:"Why advanced operations are different",body:["State-sponsored or state-linked operations may combine substantial resources, long-term access, custom tooling, and careful operational security. Yet sophistication is not a reliable attribution test by itself. Criminal groups can reuse advanced tools, and state-linked operators can use commodity malware. Define the observed capabilities rather than inferring sponsorship from complexity.","The SolarWinds Orion compromise illustrates the risk of trusted software updates and supply-chain access. A compromised build or update path can reach many organizations, but the downstream impact differs by victim and follow-on activity. Distinguish initial compromise, distribution, access, lateral movement, and actual data or service effects."]},{title:"Intrusion reconstruction",body:["Build a timeline from build-system records, update distribution, authentication events, endpoint telemetry, and network observations. Identify the trust relationship that enabled access and the controls that failed or succeeded. ATT&CK can organize techniques such as valid accounts or lateral movement, but each mapping needs supporting observations.","Check for alternative explanations and gaps. A missing log does not prove the attacker deleted it; retention or configuration may explain the absence. Preserve relevant telemetry before rotation and protect credentials and tokens that may still enable access. Avoid publishing sensitive victim details in an attribution exercise."]},{title:"Attribution and response",body:["Technical clustering can show shared infrastructure or code, while intelligence may connect an operation to an organization. Political attribution adds another layer of judgment. Report each level separately and state confidence. A tool signature associated with a group in public reporting is not proof that the group conducted every matching incident.","Response may involve coordinated containment, credential rotation, trusted rebuilds, provider action, diplomatic measures, or law enforcement. The chosen response depends on authority, evidence, and operational risk. National-security objectives do not remove the need for reliable facts, proportionate action, and clear accountability."]}],practice:{title:"Trace a trusted-update incident",scenario:"A fictional software update is followed by unusual authentication and new cloud roles.",steps:["Separate the update event from later account activity.","Identify the records needed to connect the stages.","Write technical and organizational attribution judgments separately.","Recommend evidence-preserving containment and a confidence review."],debrief:"A supply-chain investigation follows trust relationships and event sequences. It should not jump from a suspicious update to a named state without evidence."},quiz:["Why is malware reuse alone weak attribution evidence?",["Malware cannot contain identifying information.","Tools can be shared, copied, leaked, or deliberately reused as false flags.","Every criminal group writes unique code.","Reuse proves state sponsorship automatically."],1,"Shared code is one contextual clue and must be evaluated with other technical and intelligence evidence."],laws:["it-act","bnss"],sources:["solarwinds","mitre","first"],labId:"network"}),e({id:"5.7",title:"Emerging Cyber Security Threats",minutes:12,summary:"Evaluate new threats through plausible scenarios, dependencies, and controls rather than hype or a list of alarming headlines.",sections:[{title:"The changing threat landscape",body:["Ransomware, credential theft, supply-chain compromise, cloud misconfiguration, API abuse, and social engineering remain interconnected risks. AI can lower the cost of persuasive deception and assist vulnerability discovery, while also improving defensive analysis. A threat becomes relevant when a plausible actor, capability, exposure, and impact align with the organization’s context.","Deepfake voice or video can reinforce impersonation and payment fraud. A convincing call should not replace an independently verified approval process. Quantum computing raises long-term cryptographic considerations, but claims that all current encryption has already been broken are inaccurate. Distinguish present incidents, emerging capabilities, and speculative futures."]},{title:"Scenario-based risk assessment",body:["Choose a critical business process and map its identities, devices, providers, data, and recovery dependencies. Describe a realistic attack path and the controls that could prevent, detect, or limit it. Consider ordinary failures as well as deliberate attacks. A supplier outage and a ransomware incident may require similar continuity capabilities.","Use dated sources such as ENISA threat reports and relevant national advisories. A report’s ranking is not a universal probability for every organization. Record likelihood assumptions, impact, uncertainty, and the evidence behind them. Avoid copying a global trend into a local risk register without checking relevance."]},{title:"Resilience and responsible innovation",body:["Layer identity protection, patching, segmentation, backups, monitoring, and exercised response. Verify that backups are isolated, restorable, and compatible with business recovery needs. Test human approval processes for payments and privileged changes. Technology alone cannot fix a process that accepts urgency as authorization.","For AI and other new tools, define acceptable use, data handling, evaluation, human oversight, and incident escalation. Preserve provenance where feasible and avoid treating a detector’s result as conclusive. The most useful future-facing analysis identifies measurable preparations rather than predicting a single inevitable attack."]}],practice:{title:"Build a deepfake payment scenario",scenario:"A fictional manager receives a realistic voice call requesting an urgent supplier payment.",steps:["Map the approval and payment dependencies.","Identify a control that does not depend on recognizing the voice.","Define evidence to preserve if the request is fraudulent.","Write a recovery and escalation plan with clear owners."],debrief:"Out-of-band verification and dual approval can remain effective even when the deception is technically convincing."},quiz:["Which control best addresses a convincing voice-clone payment request?",["Trusting the voice if it sounds familiar.","Independent call-back and documented payment approval.","Paying faster to avoid embarrassment.","Relying only on an AI detector."],1,"A process-based verification control does not depend solely on the perceived authenticity of a voice."],laws:["it-2021","dpdp"],sources:["enisa","deepfake","it2026","nist-csf"],labId:"ai"}),e({id:"5.8",title:"Artificial Intelligence in Cyber Security",minutes:13,summary:"Use AI as a bounded analytical capability with data governance, evaluation, monitoring, and accountable human decisions.",sections:[{title:"Where AI can help",body:["AI systems can prioritize alerts, classify messages, detect unusual patterns, summarize reports, and assist malware or log analysis. Machine learning is one family of AI methods; rule-based systems and statistical analysis may be simpler and more appropriate for some tasks. Define the decision and the cost of error before selecting a model.","A model learns relationships from data and may fail when the environment changes. A phishing classifier trained on old messages can miss new wording, and a network model trained on one organization may misclassify another’s normal traffic. A high aggregate accuracy does not establish usefulness for a rare but serious threat."]},{title:"Security of the AI system",body:["Training-data poisoning, evasion, prompt injection, model extraction, and insecure integrations can affect AI systems. A language model connected to tools may act on untrusted instructions if permissions and boundaries are weak. Treat retrieved content and model output as data, not automatic authority. Use least privilege and validate actions outside the model.","Protect training data, embeddings, prompts, logs, and outputs because they can contain sensitive evidence. A public model service may have different retention and access terms from a local deployment. Do not paste confidential case material into an external service without authorization and an appropriate data-processing arrangement."]},{title:"Governance and human oversight",body:["Document the intended use, dataset, version, evaluation, limitations, and escalation process. NIST’s AI Risk Management Framework provides a voluntary governance approach; it is not an Indian evidence statute. Monitor performance, drift, and unequal error patterns. A human reviewer needs enough context and time to challenge the output.","For forensic use, preserve the original evidence and record the model-assisted transformation or summary. A generated explanation is not an independent source. Require source-linked verification and prevent the model from inventing exhibit identifiers, timestamps, or legal conclusions. The final opinion remains accountable to the evidence and the examiner."]}],practice:{title:"Draft an AI-use boundary",scenario:"A lab wants to use a language model to summarize suspicious emails.",steps:["Define permitted data and approved deployment.","Require source references and human verification.","Block automatic destructive or legal actions from model output.","Specify logging, evaluation, and incident escalation."],debrief:"A useful AI policy controls data, authority, verification, and accountability—not merely the choice of model vendor."},quiz:["What is a safe role for a language model in evidence review?",["Inventing missing timestamps.","Assisting a summary that a qualified person verifies against the source.","Automatically declaring guilt.","Replacing preservation of the original record."],1,"Model output can assist work, but it must be checked against preserved evidence and remain subject to human accountability."],laws:["dpdp","bsa"],sources:["owasp-ml","nist-csf","privacy"],labId:"ai"}),e({id:"5.9",title:"AI-Based Cyber Crime Detection Techniques",minutes:15,summary:"Evaluate classifiers through the kinds of mistakes they make, the data they learned from, and the decisions they support.",sections:[{title:"Features, labels, and learning approaches",body:["Supervised learning uses labelled examples, such as messages marked phishing or legitimate. Unsupervised methods look for structure or anomalies without relying on the same labels. Features may include URL characteristics, sender relationships, message structure, or network behavior. Feature choice and label quality can matter more than model complexity.","Data leakage occurs when information unavailable at prediction time influences training or evaluation. Randomly splitting duplicate messages can make results look unrealistically strong. Use time-aware or group-aware validation where appropriate and preserve a genuinely unseen test set. Document how labels were obtained and whether they contain human bias."]},{title:"Confusion matrix and operational metrics",body:["A true positive is a correctly flagged threat; a false positive is a benign item flagged as threatening; a false negative is a missed threat; a true negative is correctly accepted benign activity. Precision is TP/(TP+FP), recall is TP/(TP+FN), and false-positive rate is FP/(FP+TN). Each denominator answers a different question.","Accuracy can be misleading when threats are rare. A model that labels everything benign may have high accuracy but zero recall. Lowering a threshold can catch more threats while increasing analyst workload and false accusations. Choose a threshold for the operational decision, then evaluate on separate validation data and monitor real performance."]},{title:"From alert to investigation",body:["A detection score is not the probability that a person committed a crime. It is a model output under particular data and assumptions. Use the alert to prioritize review, preserve the underlying evidence, and test alternative explanations. Explainability can help identify spurious features, but an explanation is not proof of correctness.","Monitor drift, new attack patterns, and feedback loops. If analysts only investigate items the model already flags, missing threats may remain invisible. Periodically sample other traffic and update evaluation responsibly. Keep model versions and decision records so a past alert can be understood later."]}],practice:{title:"Choose a threshold for human review",scenario:"The AI lab’s synthetic validation set contains both ordinary and suspicious records.",steps:["Move the decision threshold and observe TP, FP, FN, and TN.","Calculate precision and recall at two settings.","Compare the consequences of missed threats and false alerts.","Recommend a review policy without treating the score as proof."],debrief:"There is no universally best threshold. The choice depends on harm, prevalence, review capacity, and independent safeguards."},quiz:["What does recall measure?",["The share of actual positives correctly identified.","The share of all predictions that are correct.","The number of analysts employed.","The probability that the accused is guilty."],0,"Recall is TP divided by all actual positives, TP plus FN."],laws:["bsa","dpdp"],sources:["owasp-ml","enisa","bsa"],labId:"ai"}),e({id:"5.10",title:"AI-Assisted Digital Forensic Investigation",minutes:14,summary:"Let AI assist triage and pattern discovery while preserving originals, provenance, and an examiner-controlled chain of reasoning.",sections:[{title:"Useful assistance, clear boundaries",body:["AI can help rank files, cluster similar images or messages, identify likely relevant entities, transcribe audio, and summarize large log collections. These are assistance tasks, not automatic findings of guilt. Define the input, output, confidence, and review step. Preserve the original evidence and record the model version and settings used.","A transcript can contain recognition errors, especially with accents, overlapping speakers, or poor audio. A translated summary can change nuance. An entity extractor can confuse people and organizations. Important statements must be checked against the original recording or text, with uncertainty retained where the source is unclear."]},{title:"Provenance and reproducibility",body:["Treat model output as a derived artifact linked to its input, model version, prompt or configuration, and execution time. Hash significant inputs and outputs where appropriate. A nondeterministic model may not produce identical wording on every run; reproducibility then includes the recorded output and process, not a promise of identical future generation.","Keep the model’s suggestions separate from verified observations. A generated timeline should not silently fill gaps. If an output cites an exhibit, verify that the exhibit exists and says what the summary claims. Do not allow a model to rewrite the acquisition log, custody record, or certificate as if it had witnessed the process."]},{title:"Bias, review, and testimony",body:["Training data and feature choices can bias triage toward certain languages, users, or file types. Evaluate error patterns and provide a route to challenge results. Human review must be meaningful: the reviewer needs access to the source, the ability to disagree, and enough time to inspect material decisions.","An expert using AI should be able to explain the system’s role, validation, limitations, and the independent evidence supporting the conclusion. “The AI said so” is not a forensic method. Where the model cannot be adequately explained or tested, reduce the weight placed on it and seek corroborating methods."]}],practice:{title:"Audit a generated summary",scenario:"A model produces a confident timeline from a partial mailbox export.",steps:["Compare every timestamp and actor with the source.","Mark missing events and unsupported attribution.","Record the model and prompt as a derived-processing step.","Rewrite the summary with source references and explicit uncertainty."],debrief:"Fluent language can conceal weak evidence. The examiner’s job is to test the summary, not polish an unsupported conclusion."},quiz:["How should an AI-generated evidence summary be treated?",["As an independent original source.","As a derived aid requiring source-linked verification.","As a replacement for the custody record.","As proof of every statement it contains."],1,"The summary depends on the input and model process; it does not become independent proof by being generated."],laws:["bsa","dpdp"],sources:["bsa","owasp-ml","privacy"],labId:"ai"}),e({id:"5.11",title:"Machine Learning Applications in Cyber Forensics",minutes:15,summary:"Connect learning methods to forensic tasks while keeping validation, explainability, and evidential limitations visible.",sections:[{title:"Classification, clustering, and anomaly detection",body:["Classification can support malware-family labeling, message filtering, or file categorization. Clustering can group related artifacts without predefined labels. Anomaly detection can highlight unusual processes or network behavior. None of these methods automatically establishes who performed an action or whether the behavior satisfies a criminal offence.","Decision trees and random forests can provide interpretable feature-based decisions; support vector machines and neural networks may capture different relationships. Clustering results depend on distance measures and feature scaling. An unusual event can be a new legitimate business process. Choose a method that fits the data and question, then validate it appropriately."]},{title:"Evaluation and forensic validity",body:["Separate training, validation, and test data. Prevent duplicates and related records from leaking across splits. Evaluate with metrics suited to prevalence and harm, and examine errors by relevant subgroup or scenario. A benchmark result from a public dataset may not transfer to a different device, application version, or network.","Document preprocessing, feature extraction, model parameters, random seeds where relevant, and software versions. Preserve the original evidence and the derived feature table. Where a proprietary model cannot be fully inspected, state that limitation and seek independent performance testing and corroboration."]},{title:"Explainability and courtroom communication",body:["Feature importance, local explanations, and example-based reasoning can help an examiner understand a model. They do not prove causation or guarantee that the model used a legally relevant reason. A classifier may rely on an incidental artifact correlated with the training labels rather than the underlying malicious behavior.","Present the model as one component of the examination. Explain what it predicted, how it was tested, where it failed, and what independent evidence supports the finding. Do not translate a score into a claim about the probability of guilt. The court needs an accountable explanation of the evidence, not a leaderboard result."]}],practice:{title:"Review a model-validation claim",scenario:"A paper reports 99% accuracy on a malware dataset with many duplicate samples.",steps:["Identify possible leakage and prevalence problems.","Request precision, recall, confusion matrix, and split methodology.","Test whether the dataset matches the intended environment.","Write a limitation suitable for a forensic report."],debrief:"A high headline metric is not enough. Validity depends on data separation, representativeness, error analysis, and the intended use."},quiz:["Why can duplicate samples inflate a model’s test performance?",["They make the model impossible to run.","Near-identical examples may appear in both training and test sets.","They guarantee perfect real-world performance.","They eliminate the need for labels."],1,"Leakage between splits can measure memorization or similarity rather than genuine generalization."],laws:["bsa","dpdp"],sources:["owasp-ml","bsa","enisa"],labId:"ai"}),e({id:"5.12",title:"Future Trends in Cyber Forensics, AI and Cyber Security",minutes:13,summary:"Prepare for changing evidence sources, stronger provenance, privacy-preserving methods, and accountable automation.",sections:[{title:"New evidence environments",body:["Evidence will increasingly span cloud services, connected vehicles, wearables, industrial systems, and AI-mediated interactions. Each source has its own data model, retention, ownership, and access constraints. The forensic challenge is not only volume; it is understanding which system generated a record and what transformations occurred before collection.","Synthetic-media detection and provenance will remain complementary. A detector can produce false positives and may degrade as generation methods change. Provenance mechanisms can help establish a recorded history, but absence of provenance does not prove fabrication. Legal and technical analysis must keep pace with the actual notified rules and available standards."]},{title:"Automation with accountable boundaries",body:["AI-assisted triage, cross-source correlation, and automated reporting can reduce repetitive work. They also introduce risks of hidden bias, data leakage, invented details, and overreliance. Design systems with explicit authority boundaries, audit logs, human review, and a way to reconstruct how an output was produced.","Privacy-preserving collaboration, improved cloud auditability, and standardized exchange formats may support investigations without unnecessary raw-data sharing. These are developing capabilities, not universal solutions. Evaluate claims against a defined use case, independent testing, and the applicable legal framework rather than assuming a technology removes governance problems."]},{title:"A professional learning plan",body:["Build competence in legal interpretation, evidence handling, operating systems, networks, and critical evaluation of models. Practise explaining uncertainty to non-specialists. Follow official amendments, current case law, supported tool documentation, and peer-reviewed research. A tool certificate alone does not establish broad forensic competence.","Use the course’s case files and simulations to connect the units: identify the legal issue, preserve the source, test alternative explanations, evaluate the evidence, and communicate the result. The durable skill is a disciplined method. Technologies will change, but authority, integrity, reproducibility, and fairness remain central."]}],practice:{title:"Design your next investigation",scenario:"Choose one fictional case from the reading room and imagine a new cloud or AI evidence source.",steps:["Write the legal and technical questions.","Identify the source, controller, retention, and lawful access route.","Plan verification, human review, and alternative explanations.","Prepare a printable evidence plan with sources and limitations."],debrief:"A future-ready investigator combines curiosity with boundaries: test new methods, preserve the evidence, and remain accountable for the conclusion."},quiz:["Which capability is most durable as forensic technology changes?",["Memorizing one tool’s menu.","A disciplined method of authority, preservation, validation, and clear reasoning.","Trusting every automated score.","Assuming provenance is never relevant."],1,"Tools change; accountable investigative reasoning remains the foundation of reliable forensic work."],laws:["bsa","it-2021","dpdp"],sources:["it2026","nist-csf","owasp-ml","enisa"],labId:"ai"})],g=Object.fromEntries(f.map(a=>[a.id,a]));async function h({params:a}){let{id:b}=await a;return{title:g[b]?.title||"Lesson"}}async function i({params:a}){let{id:e}=await a,f=g[e];return f||(0,c.notFound)(),(0,b.jsx)(d.default,{topic:f},e)}f.map(a=>a.question),f.reduce((a,b)=>a+[b.summary,...b.objectives,...b.sections.flatMap(a=>[a.title,...a.body]),b.practice.scenario,...b.practice.steps,b.practice.debrief].join(" ").split(/\s+/).length,0),a.s(["default",0,i,"dynamicParams",0,!1,"generateMetadata",0,h,"generateStaticParams",0,function(){return f.map(a=>({id:a.id}))}],31580)},44200,a=>{a.n(a.i(31580))}];

